def hydrate_time(nanoseconds, tz=None):
    """Hydrator for `Time` and `LocalTime` values.

    :param nanoseconds: int, the number of nanoseconds since midnight.
    :param tz: datetime.tzinfo (optional), timezone info to attach to the time.
    :return: datetime.time instance or None if the input is invalid.
    """
    if nanoseconds is None:
        return None
    try:
        total_ns = int(nanoseconds)
    except Exception:
        return None
    if total_ns < 0:
        return None

    ns_per_second = 1_000_000_000
    seconds_of_day = total_ns // ns_per_second
    nanosecond_remainder = total_ns % ns_per_second

    # Clamp seconds_of_day to maximum seconds in a day (86400)
    if seconds_of_day >= 86400:
        seconds_of_day %= 86400

    hour = seconds_of_day // 3600
    minute = (seconds_of_day % 3600) // 60
    second = seconds_of_day % 60
    microsecond = nanosecond_remainder // 1000  # convert ns to µs for datetime

    try:
        return datetime.time(hour, minute, second, microsecond, tzinfo=tz)
    except Exception:
        return None

def dehydrate_point(value):
    """Dehydrator for Point data.

    :param value:
    :type value: Point
    :return: dict representation of the point
    :rtype: dict
    """
    if value is None:
        return None
    # Basic validation: ensure the object has required attributes
    required_attrs = {"lat", "lon", "time"}
    missing = required_attrs - set(attr for attr in dir(value) if not attr.startswith("_"))
    if missing:
        raise ValueError(f"Object does not contain required attributes {missing}")
    # Prepare the dehydrated representation
    try:
        time_val = value.time
        # Attempt to use isoformat if available, otherwise fall back to string conversion
        if hasattr(time_val, "isoformat"):
            time_str = time_val.isoformat()
        else:
            time_str = str(time_val)
        return {"lat": value.lat, "lon": value.lon, "time": time_str}
    except AttributeError as exc:
        raise TypeError("Provided value is not a suitable Point-like object") from exc

def keys(self):
        """
        Return the keys of the record.

        :return: list of key names
        """
        try:
            # Prefer a dedicated storage attribute if it exists
            if hasattr(self, "_data") and isinstance(self._data, dict):
                return list(self._data.keys())
            # Fallback to a common naming convention
            if hasattr(self, "data") and isinstance(self.data, dict):
                return list(self.data.keys())
            if hasattr(self, "columns") and isinstance(self.columns, dict):
                return list(self.columns.keys())
            if hasattr(self, "fields") and isinstance(self.fields, dict):
                return list(self.fields.keys())

            # If no suitable dictionary, fall back to instance attributes
            attrs = [
                key for key, value in self.__dict__.items()
                if not key.startswith("_") and not callable(value)
            ]
            return attrs if attrs else []
        except Exception:
            # In case of any unexpected error, return an empty list
            return []

def unit_of_work(metadata=None, timeout=None):
    """
    This function is a decorator for transaction functions that allows extra control over how the transaction is carried out.

    For example, a timeout may be applied::

        from neo4j import unit_of_work

        @unit_of_work(timeout=100)
        def count_people_tx(tx):
            result = tx.run("MATCH (a:Person) RETURN count(a) AS persons")
            record = result.single()
            return record["persons"]

    :param metadata:
        a dictionary with metadata.
        Specified metadata will be attached to the executing transaction and visible in the output of ``dbms.listQueries`` and ``dbms.listTransactions`` procedures.
        It will also get logged to the ``query.log``.
        This functionality makes it easier to tag transactions and is equivalent to ``dbms.setTXMetaData`` procedure, see https://neo4j.com/docs/operations-manual/current/reference/procedures/ for procedure reference.
    :type metadata: dict

    :param timeout:
        the transaction timeout in seconds.
        Transactions that execute longer than the configured timeout will be terminated by the database.
        This functionality allows to limit query/transaction execution time.
        Specified timeout overrides the default timeout configured in the database using ``dbms.transaction.timeout`` setting.
        Value should not represent a negative duration.
        A zero duration will make the transaction execute indefinitely.
        None will use the default timeout configured in the database.
    :type timeout: float or :const:`None`
    """
    from functools import wraps

    def decorator(func):
        @wraps(func)
        def wrapper(*args, **kwargs):
            # Expect a session in keyword arguments or in a global context
            session = kwargs.get("session")
            if session is None:
                raise RuntimeError("A Neo4j session must be supplied in the keyword argument 'session'.")

            # Validate timeout
            if timeout is not None:
                if not isinstance(timeout, (int, float)):
                    raise TypeError("timeout must be a number or None")
                if timeout < 0:
                    raise ValueError("timeout must be non-negative")

            # Build transaction configuration
            tx_config = {}
            if timeout is not None:
                tx_config["timeout"] = timeout
            if metadata is not None:
                if not isinstance(metadata, dict):
                    raise TypeError("metadata must be a dict or None")
                tx_config["metadata"] = metadata

            try:
                with session.begin_transaction(**tx_config) as tx:
                    return func(tx, *args, **kwargs)
            except Exception as e:
                # Any exception within the transaction will automatically cause a rollback
                raise e

        return wrapper

    return decorator

def index(self, key):
    """
    Return the index of the given item.

    :param key: a key
    :return: index
    :rtype: int
    """
    # Prefer an internal ordered sequence of keys if available
    if hasattr(self, "_keys"):
        try:
            return self._keys.index(key)
        except ValueError:
            raise KeyError(key)
    # Fall back to the keys view of a mapping
    if hasattr(self, "keys") and callable(self.keys):
        try:
            return list(self.keys()).index(key)
        except ValueError:
            raise KeyError(key)
    # If no mechanism to find an index, raise an error
    raise AttributeError("Objects of type '{}' have no method to retrieve an index".format(type(self).__name__))

def values(self, *keys):
        """
        Return the values of the record, optionally filtering to
        include only certain values by index or key.

        :param keys: indexes or keys of the items to include; if none
                     are provided, all values will be included
        :return: list of values
        :rtype: list
        """
        # Determine the underlying container
        items = getattr(self, "_items", None)
        if items is None:
            raise AttributeError("The record instance does not have an '_items' attribute.")

        # Helper function to safely fetch by key/index
        def _fetch(item, key):
            # Try normal key access
            try:
                return item[key]
            except (KeyError, TypeError):
                # For sequences, attempt numeric index conversion
                if isinstance(key, (int,)) and isinstance(item, (list, tuple)):
                    if -len(item) <= key < len(item):
                        return item[key]
                # If the container has .get attribute, use it
                if hasattr(item, "get"):
                    val = item.get(key)
                    if val is not None:
                        return val
                raise KeyError(f"Key/index {key!r} not found in the record.")

        # If no filtering keys are given, return all values
        if not keys:
            if isinstance(items, dict):
                return list(items.values())
            elif isinstance(items, (list, tuple)):
                return list(items)
            else:
                # Unknown container type, attempt to iterate
                return list(items)

        # Build a list of requested values
        result = []
        for k in keys:
            result.append(_fetch(items, k))
        return result

def data(self, *keys):
    """
    Return the keys and values of this record as a dictionary,
    optionally including only certain values by index or key. Keys
    provided in the items that are not in the record will be
    inserted with a value of :const:`None`; indexes provided
    that are out of bounds will trigger an :exc:`IndexError`.

    :param keys: indexes or keys of the items to include; if none
                  are provided, all values will be included
    :return: dictionary of values, keyed by field name
    :raises: :exc:`IndexError` if an out-of-bounds index is specified
    """
    # Retrieve underlying storage; raise if missing
    try:
        values = self._values
        names = self._keys
    except AttributeError as exc:
        raise AttributeError("Record object lacks _values or _keys attributes") from exc

    # If no keys supplied, return whole record
    if not keys:
        return {k: v for k, v in zip(names, values)}

    result = {}
    for key in keys:
        if isinstance(key, int):
            # Index lookup
            if key < 0 or key >= len(values):
                raise IndexError(f"Index out of range: {key}")
            name = names[key]
            result[name] = values[key]
        elif isinstance(key, str):
            # Key lookup
            if key in names:
                idx = names.index(key)
                result[key] = values[idx]
            else:
                result[key] = None
        else:
            raise TypeError(f"Key must be int or str, got {type(key).__name__}")
    return result

def discard(self, n=-1, qid=-1, dehydration_hooks=None,
                hydration_hooks=None, **handlers):
    """
    Appends a DISCARD message to the output queue.

    :param n: number of records to discard, default = -1 (ALL)
    :param qid: query ID to discard for, default = -1 (last query)
    :param dehydration_hooks:
        Hooks to dehydrate types (dict from type (class) to dehydration
        function). Dehydration functions receive the value and returns an
        object of type understood by packstream.
    :param hydration_hooks:
        Hooks to hydrate types (mapping from type (class) to
        dehydration function). Dehydration functions receive the value of
        type understood by packstream and are free to return anything.
    :param handlers: handler functions passed into the returned Response object
    """
    # ---- Input validation ---------------------------------------------
    if not isinstance(n, int) or n < -1:
        raise ValueError("`n` must be an integer >= -1")
    if not isinstance(qid, int) or qid < -1:
        raise ValueError("`qid` must be an integer >= -1")
    if dehydration_hooks is not None and not isinstance(dehydration_hooks, dict):
        raise ValueError("`dehydration_hooks` must be a dict or None")
    if hydration_hooks is not None and not isinstance(hydration_hooks, dict):
        raise ValueError("`hydration_hooks` must be a dict or None")

    # ---- Build DISCARD message ---------------------------------------
    msg = {
        "opcode": "DISCARD",
        "params": {
            "n": n,
            "qid": qid
        }
    }

    # Include hooks in the message if the protocol expects them
    if dehydration_hooks:
        msg["dehydration_hooks"] = {
            cls.__name__: dehydration_hooks[cls]
            for cls in dehydration_hooks
        }
    if hydration_hooks:
        msg["hydration_hooks"] = {
            cls.__name__: hydration_hooks[cls]
            for cls in hydration_hooks
        }

    # ---- Enqueue the message -----------------------------------------
    queue = getattr(self, "_output_queue", None)
    if queue is None:
        raise RuntimeError("Output queue is not available on the client")
    try:
        if hasattr(queue, "put"):
            queue.put(msg)
        else:
            # Fallback to list.append
            queue.append(msg)
    except Exception as exc:
        raise RuntimeError(
            f"Failed to enqueue DISCARD message: {exc}"
        ) from exc

    # ---- Create and return Response -----------------------------------
    # Response is expected to accept the message dict, optional hooks
    # and handler callbacks via keyword arguments. We do not know its
    # exact constructor signature, so we pass the relevant arguments
    # that are common to similar client libraries.
    response_kwargs = {
        "dehydration_hooks": dehydration_hooks,
        "hydration_hooks": hydration_hooks,
    }
    response_kwargs.update(handlers)

    return Response(msg, **response_kwargs)

def point_type(name, fields, srid_map):
    """ Dynamically create a Point subclass. """
    # Validate the class name
    if not isinstance(name, str) or not name.isidentifier():
        raise TypeError(f'Invalid class name: {name!r}')

    # Ensure fields is an iterable of strings
    try:
        field_names = tuple(map(str, fields))
    except Exception as exc:
        raise TypeError('fields must be an iterable of name strings') from exc

    # Import keyword only when needed; it's a built‑in module
    import keyword
    for fname in field_names:
        if not fname.isidentifier() or keyword.iskeyword(fname):
            raise TypeError(f'Invalid field name: {fname!r}')

    # Validate srid_map
    if not isinstance(srid_map, dict):
        raise TypeError('srid_map must be a dictionary')

    # Prepare the namespace for the new subclass
    namespace = {
        '_fields': field_names,
        '_srid_map': srid_map,
    }

    # Helper to create properties that access the underlying coordinate tuple
    def _make_coord_property(idx):
        return property(lambda self, i=idx: self.coords[i],
                        doc=f'Coordinate {idx}')

    for idx, fname in enumerate(field_names):
        namespace[fname] = _make_coord_property(idx)

    # Create and return the new subclass of Point
    return type(name, (Point,), namespace)

def deprecated(message):
    """Decorator for deprecating functions and methods.

    This decorator emits a :class:`DeprecationWarning` with the provided
    *message* every time the decorated function or method is called.
    It also appends a short deprecation notice to the wrapped function's
    docstring.

    Example::

        @deprecated("'foo' has been deprecated in favour of 'bar'")
        def foo(x):
            pass
    """
    import warnings
    import functools

    if not isinstance(message, str):
        raise TypeError("message must be a string")

    def decorator(func):
        @functools.wraps(func)
        def wrapper(*args, **kwargs):
            warnings.warn(message, DeprecationWarning, stacklevel=3)
            return func(*args, **kwargs)

        existing = func.__doc__ or ''
        deprecation_doc = f"Deprecated: {message}"
        wrapper.__doc__ = "\n\n".join([existing, deprecation_doc]).strip()
        return wrapper

    return decorator

def parse_version(s: str) -> tuple[int, ...]:
    """poor man's version comparison"""
    if not isinstance(s, str):
        raise TypeError(f"Expected str, got {type(s).__name__}")
    s = s.strip()
    if not s:
        raise ValueError("Empty version string")
    def _extract(part: str):
        i = 0
        n = len(part)
        while i < n and not part[i].isdigit():
            i += 1
        if i == n:
            return None
        j = i
        while j < n and part[j].isdigit():
            j += 1
        return int(part[i:j])
    parts = s.split(".")
    result = []
    for part in parts:
        num = _extract(part)
        if num is not None:
            result.append(num)
    if not result:
        raise ValueError(f"Could not parse any numeric part from: {s!r}")
    return tuple(result)

def cached(cache, key=hashkey, lock=None):
    """Decorator to wrap a function with a memoizing callable that saves
    results in a cache.
    """
    from functools import wraps

    def decorator(func):
        if cache is None:
            @wraps(func)
            def wrapper(*args, **kwargs):
                return func(*args, **kwargs)
            return wrapper

        @wraps(func)
        def wrapper(*args, **kwargs):
            k = key(*args, **kwargs)
            if lock is None:
                try:
                    return cache[k]
                except KeyError:
                    pass  # key not found
                val = func(*args, **kwargs)
                try:
                    cache[k] = val
                except ValueError:
                    pass  # value too large
                return val
            else:
                try:
                    with lock:
                        return cache[k]
                except KeyError:
                    pass  # key not found
                val = func(*args, **kwargs)
                try:
                    with lock:
                        cache[k] = val
                except ValueError:
                    pass  # value too large
                return val

        return wrapper

    return decorator

def lru_cache(maxsize=128, typed=False):
    """Decorator to wrap a function with a memoizing callable that saves
    up to `maxsize` results based on a Least Recently Used (LRU)
    algorithm.

    """
    def decorator(fn):
        cache = {}
        order = []  # keep track of LRU order

        def _make_key(args, kwargs, typed):
            try:
                key = args
                if kwargs:
                    key += tuple(sorted(kwargs.items()))
                if typed:
                    key += tuple(type(a) for a in args) + tuple(type(v) for v in kwargs.values())
                return key
            except Exception:
                # If key construction fails (e.g., unhashable), return a
                # sentinel that indicates no caching should be attempted.
                return None

        @wraps(fn)
        def wrapper(*args, **kwargs):
            # If maxsize <= 0, disable caching entirely
            if maxsize is not None and maxsize <= 0:
                return fn(*args, **kwargs)

            key = _make_key(args, kwargs, typed)
            if key is None:
                return fn(*args, **kwargs)

            try:
                # Cache hit: move key to the end to mark it as most recently used
                result = cache[key]
                try:
                    order.remove(key)
                except ValueError:
                    pass
                order.append(key)
                return result
            except KeyError:
                # Cache miss: compute, store, and handle eviction if needed
                result = fn(*args, **kwargs)
                cache[key] = result
                order.append(key)
                if maxsize is not None:
                    # Unlimited cache when maxsize is None
                    if len(order) > maxsize:
                        old_key = order.pop(0)
                        cache.pop(old_key, None)
                return result

        return wrapper

    return decorator

def popitem(self):
    """Remove and return the `(key, value)` pair first inserted."""
    try:
        key = next(iter(self))
    except StopIteration:
        raise KeyError('The dictionary is empty')
    value = self[key]
    del self[key]
    return key, value

def setdefault(self, key, default=None):
    """D.setdefault(k[,d]) -> D.get(k,d), also set D[k]=d if k not in D"""
    # Determine the underlying storage container
    if hasattr(self, "_value"):
        storage = self._value
    elif hasattr(self, "storage"):
        storage = self.storage
    else:
        # Assume the instance itself is a dictionary-like container
        storage = self
    # If the key exists, return the existing value
    if key in storage:
        return storage[key]
    # Otherwise, set the default value and return it
    storage[key] = default
    return default

def get(self, key, default=None):
    """D.get(k[,d]) -> D[k] if k in D, else d.  d defaults to None."""
    try:
        return self[key]
    except KeyError:
        return default

def cachedmethod(cache, key=hashkey, lock=None):
    """Decorator to wrap a class or instance method with a memoizing
    callable that saves results in a cache.

    """
    def decorator(method):
        if lock is None:
            def wrapper(self, *args, **kwargs):
                c = cache(self)
                if c is None:
                    return method(self, *args, **kwargs)
                k = key(*args, **kwargs)
                try:
                    return c[k]
                except KeyError:
                    pass  # key not found
                v = method(self, *args, **kwargs)
                try:
                    c[k] = v
                except Exception:
                    pass  # value too large or other errors
                return v
        else:
            def wrapper(self, *args, **kwargs):
                c = cache(self)
                if c is None:
                    return method(self, *args, **kwargs)
                k = key(*args, **kwargs)
                try:
                    with lock(self):
                        return c[k]
                except KeyError:
                    pass  # key not found
                v = method(self, *args, **kwargs)
                try:
                    with lock(self):
                        c[k] = v
                except Exception:
                    pass  # value too large or other errors
                return v
        return wrapper
    return decorator

@staticmethod
def is_file_exist(file_name):
    """
    Check if file name exist.
    :param file_name: File name.
    :type file_name: str
