def minimalBases(classes):
    """Reduce a list of base classes to its ordered minimum equivalent"""
    try:
        iterable = list(classes)
    except Exception:
        raise TypeError("classes must be an iterable of types")
    seen = set()
    unique = []
    for cls in iterable:
        if not isinstance(cls, type):
            raise TypeError(f"{cls!r} is not a type")
        if cls not in seen:
            seen.add(cls)
            unique.append(cls)
    result = []
    for cls in unique:
        # Skip cls if there exists another base that is a subclass of cls
        if any(other is not cls and issubclass(other, cls) for other in unique):
            continue
        result.append(cls)
    return result

def namesAndDescriptions(self, all=False):  # pylint:disable=redefined-builtin
    """Return attribute names and descriptions defined by interface."""
    import inspect
    cls = self.__class__
    names = []
    seen = set()
    classes = (cls,) if not all else cls.__mro__
    for c in classes:
        for name, obj in inspect.getmembers(c):
            if name in seen:
                continue
            if name.startswith('_') and not all:
                continue
            if isinstance(obj, property):
                doc = obj.fget.__doc__ if obj.fget else None
            elif inspect.isroutine(obj):
                doc = obj.__doc__
            else:
                doc = None
            if doc:
                names.append((name, doc.strip()))
            seen.add(name)
    return names

def _normalizeargs(sequence, output=None):
    """Normalize declaration arguments

    Normalization arguments might contain Declarions, tuples, or single
    interfaces.

    Anything but individial interfaces or implements specs will be expanded.
    """
    if output is None:
        output = []

    # Helper to check for Implements from zope.interface
    try:
        from zope.interface.declarations import Implements
    except Exception:
        Implements = None

    # If the sequence itself is a class (interface) or an Implements spec,
    # add it directly to the output.
    if isinstance(sequence, Implements) or isinstance(sequence, type):
        output.append(sequence)
        return output

    # If sequence is an iterable (but not a string or bytes), recurse into each element.
    if hasattr(sequence, "__iter__") and not isinstance(sequence, (str, bytes)):
        try:
            for item in sequence:
                _normalizeargs(item, output)
        except Exception as e:
            raise RuntimeError("Argument `sequence` is not valid") from e
    else:
        # Non-iterable, non-interface objects are ignored.
        pass

    return output

def _c_optimizations_required():
    """
    Return a true value if the C optimizations are required.

    This uses the ``PURE_PYTHON`` variable as documented in `_use_c_impl`.
    """
    try:
        return not PURE_PYTHON
    except NameError:
        # If PURE_PYTHON is not defined, default to C optimizations not required
        return False

def reset(self):
    """
    Reset the histogram.

    Current context is reset to an empty dict.
    Bins are reinitialized with the *initial_value*
    or with *make_bins()* (depending on the initialization).
    """
    # Reset the current context
    self.context = {}

    # Reinitialize bins
    try:
        # If an explicit initial_value is defined, use it to set all bins
        if hasattr(self, "initial_value") and self.initial_value is not None:
            # Determine the number of bins from existing bin storage if available
            if hasattr(self, "bins") and isinstance(self.bins, (list, tuple)):
                bin_count = len(self.bins)
            elif hasattr(self, "n_bins"):
                bin_count = self.n_bins
            else:
                raise AttributeError("Cannot determine the number of bins for reinitialization.")

            # Recreate the bins list with the initial value
            self.bins = [self.initial_value] * bin_count

        # If no explicit initial_value, fall back to make_bins
        else:
            if not hasattr(self, "make_bins") or not callable(self.make_bins):
                raise AttributeError("No method 'make_bins' available for bin reinitialization.")
            # Use the provided method to generate a fresh bin configuration
            self.bins = self.make_bins()

    except Exception as exc:
        # Wrap any exception to provide clearer debugging info
        raise RuntimeError(f"Failed to reinitialize histogram bins: {exc}") from exc

def to_csv(self, separator=",", header=None):
    """.. deprecated:: 0.5 in Lena 0.5 to_csv is not used.
          Iterables are converted to tables.

    Convert graph's points to CSV.

    *separator* delimits values, the default is comma.

    *header*, if not ``None``, is the first string of the output
    (new line is added automatically).

    Since a graph can be multidimensional,
    for each point first its coordinate is converted to string
    (separated by *separator*), then each part of its value.

    To convert :class:`Graph` to CSV inside a Lena sequence,
    use :class:`lena.output.ToCSV`.
    """
    # Build list of CSV rows
    rows = []
    for point in self:
        try:
            # Assume a point is either a tuple (coord, value) or a single coordinate
            if isinstance(point, tuple) and len(point) == 2:
                coord, value = point
            else:
                coord, value = point, None
        except Exception:
            # Skip points that cannot be unpacked
            continue

        # Convert coordinate to string
        if isinstance(coord, (list, tuple)):
            try:
                coord_str = separator.join(map(str, coord))
            except Exception:
                coord_str = str(coord)
        else:
            coord_str = str(coord)

        # Convert value to string (if any)
        if value is not None:
            if isinstance(value, (list, tuple)):
                try:
                    value_str = separator.join(map(str, value))
                except Exception:
                    value_str = str(value)
            else:
                value_str = str(value)
            row = f"{coord_str}{separator}{value_str}"
        else:
            row = coord_str

        rows.append(row)

    # Assemble final CSV string
    output_lines = []
    if header is not None:
        output_lines.append(str(header))
    output_lines.extend(rows)
    return "\n".join(output_lines) + ("\n" if output_lines else "")

def _get_err_indices(self, coord_name):
    """Get error indices corresponding to a coordinate."""
    # Ensure the coordinate name is a string
    if not isinstance(coord_name, str):
        raise TypeError("coord_name must be a string")

    # Retrieve the container that holds the variables
    try:
        variables = self._variables
    except AttributeError:
        raise AttributeError("The object has no '_variables' attribute")

    # If '_variables' is a dict, iterate over its keys; if a list/tuple, iterate directly
    err_indices = []
    if isinstance(variables, dict):
        iterable = variables.items()  # (key, value)
    elif isinstance(variables, (list, tuple)):
        iterable = enumerate(variables)  # (index, value)
    else:
        # Fall back to treating it as an iterable of variables with an implicit index
        iterable = enumerate(variables)

    for idx, var in iterable:
        # Extract the variable name
        name = None
        if isinstance(var, dict):
            name = var.get("name") or var.get("var") or None
        elif hasattr(var, "name"):
            name = getattr(var, "name")
        elif isinstance(var, str):
            name = var

        if not isinstance(name, str):
            continue

        # Check for common error suffixes
        if name.startswith(coord_name):
            suffix = name[len(coord_name) :]
            suffix_lc = suffix.lower()
            if suffix_lc.startswith("_err") or suffix_lc.startswith("_error"):
                # Using idx from enumeration
                if isinstance(iterable, dict.items()):
                    # For dict, use the key as index if it is numeric
                    if isinstance(idx, int):
                        err_indices.append(idx)
                    else:
                        err_indices.append(name)
                else:
                    err_indices.append(idx)

    return err_indices

def _update_context(self, context):
        """Update *context* with the properties of this graph.

        *context.error* is appended with indices of errors.
        Example subcontext for a graph with fields "E,t,error_E_low":
        {"error": {"x_low": {"index": 2}}}.
        Note that error names are called "x", "y" and "z"
        (this corresponds to first three coordinates,
        if they are present), which allows to simplify plotting.
        Existing values are not removed
        from *context.value* and its subcontexts.

        Called on "destruction" of the graph (for example,
        in :class:`.ToCSV`). By destruction we mean conversion
        to another structure (like text) in the flow.
        The graph object is not really destroyed in this process.
        """
        # Gather all public attributes that are not callables
        try:
            fields = [k for k in self.__dict__
                      if not k.startswith('_')
                      and not callable(getattr(self, k, None))]
        except Exception:
            # If introspection fails, do not update
            return

        # Build index mapping for all fields
        field_indices = {k: i for i, k in enumerate(fields)}

        # Determine coordinate fields (first three non-error fields)
        coord_fields = [k for k in fields if not k.startswith('error_')][:3]

        # Reverse mapping from coordinate field name to letter
        reverse_coord_map = {}
        for letter, fname in zip('xyz', coord_fields):
            if fname:
                reverse_coord_map[fname] = letter

        # Ensure context.error structure is present
        try:
            if not hasattr(context, 'error') or context.error is None:
                context.error = {}
            if 'error' not in context.error:
                context.error['error'] = {}
        except Exception:
            # Context structure not writable; skip
            return

        # Process error attributes
        for attr in fields:
            if not attr.startswith('error_'):
                continue
            rest = attr[6:]  # strip 'error_'
            # Split on first underscore to separate base coordinate name
            if '_' in rest:
                base, suffix = rest.split('_', 1)
                suffix = '_' + suffix
            else:
                base, suffix = rest, ''
            # Map base name to coordinate letter, fallback to 'x'
            coord_letter = reverse_coord_map.get(base, reverse_coord_map.get(base[:1], 'x'))
            error_name = coord_letter + suffix

            # Index of this error field in the field list
            idx_error = field_indices.get(attr)
            if idx_error is None:
                continue

            # Append to context.error
            context.error['error'].setdefault(error_name, {})
            context.error['error'][error_name]['index'] = idx_error

        # Note that existing context.value and its subcontexts remain untouched.

def is_fill_request_seq(seq):
    """Test whether *seq* can be converted to a FillRequestSeq.

    True only if it is a FillRequest element
    or contains at least one such,
    and it is not a Source sequence.
    """
    # Direct FillRequest instance is always acceptable
    if isinstance(seq, FillRequest):
        return True
    # A Source instance is explicitly excluded
    if isinstance(seq, Source):
        return False
    # Try to iterate over the sequence to find a FillRequest
    try:
        for item in seq:
            if isinstance(item, FillRequest):
                return True
        return False
    except TypeError:
        # Not iterable
        return False

def is_fill_request_el(obj):
    """Object contains executable methods 'fill' and 'request'."""
    try:
        fill_attr = getattr(obj, 'fill', None)
        request_attr = getattr(obj, 'request', None)
        return callable(fill_attr) and callable(request_attr)
    except Exception:
        return False

def is_run_el(obj):
    """Object contains executable method 'run'."""
    if obj is None:
        return False
    try:
        fn = getattr(obj, "run")
    except Exception:
        return False
    return callable(fn)

def is_fill_compute_el(obj):
    """Object contains executable methods 'fill' and 'compute'."""
    if obj is None:
        return False
    try:
        return all(callable(getattr(obj, name, None)) for name in ("fill", "compute"))
    except Exception:
        return False

def difference(d1, d2, level=-1):
    """
    Return a dictionary with items from *d1* not contained in *d2*.

    *level* sets the maximum depth of recursion. For infinite recursion,
    set that to -1. For level 1,
    if a key is present both in *d1* and *d2* but has different values,
    it is included into the difference.
    See :func:`intersection` for more details.

    *d1* and *d2* remain unchanged. However, *d1* or some of its
    subdictionaries may be returned directly.
    Make a deep copy of the result when appropriate.

    .. versionadded:: 0.5
       add keyword argument *level*.
    """
    # Helper recursive function
    def _diff(dict1, dict2, depth):
        result = {}
        for key, val in dict1.items():
            if key not in dict2:
                # key only in dict1
                result[key] = val
            else:
                other_val = dict2[key]
                # if both are dicts and we can recurse
                if isinstance(val, dict) and isinstance(other_val, dict):
                    if depth == -1 or depth > 0:
                        # compute sub-difference
                        sub_depth = depth-1 if depth > 0 else -1
                        sub_diff = _diff(val, other_val, sub_depth)
                        if sub_diff:
                            result[key] = sub_diff
                else:
                    # non-dict values, include if they differ
                    if val != other_val:
                        result[key] = val
        return result

    # Validate inputs
    if not isinstance(d1, dict) or not isinstance(d2, dict):
        raise TypeError("Both d1 and d2 must be dictionaries")
    if not isinstance(level, int):
        raise TypeError("level must be an integer")

    return _diff(d1, d2, level)

def generate_default_observer_schema_dict(manifest_dict, first_level=False):
    """
    Together with :func:`generate_default_observer_schema_list`, this function is
    called recursively to generate part of a default ``observer_schema`` from part of a
    Kubernetes resource, defined respectively by ``manifest_dict`` or ``manifest_list``.

    Args:
        manifest_dict (dict): Partial Kubernetes resources
        first_level (bool, optional): If True, indicates that the dictionary represents
            the whole observer schema of a Kubernetes resource

    Returns:
        dict: Generated partial observer_schema

    This function creates a new dictionary from ``manifest_dict`` and replaces all
    non-list and non-dict values by ``None``.

    In case of ``first_level`` dictionary (i.e. complete ``observer_schema`` for a
    resource), the values of the identifying fields are copied from the manifest file.
    """

    def _process_list(lst):
        new_list = []
        for item in lst:
            if isinstance(item, dict):
                new_list.append(_process_dict(item, False))
            elif isinstance(item, list):
                new_list.append(_process_list(item))
            else:
                new_list.append(None)
        return new_list

    def _process_dict(d, is_first):
        res = {}
        for k, v in d.items():
            if isinstance(v, dict):
                if is_first and k == "metadata":
                    # Copy only the name and namespace fields from metadata
                    sub = {}
                    for mk, mv in v.items():
                        if mk in ("name", "namespace"):
                            sub[mk] = mv
                        else:
                            sub[mk] = None
                    res[k] = sub
                else:
                    res[k] = _process_dict(v, False)
            elif isinstance(v, list):
                res[k] = _process_list(v)
            else:
                if is_first and k in ("apiVersion", "kind"):
                    res[k] = v
                else:
                    res[k] = None
        return res

    if not isinstance(manifest_dict, dict):
        raise TypeError("manifest_dict must be a dictionary")
    return _process_dict(manifest_dict, first_level)

def update_last_applied_manifest_list_from_resp(
    last_applied_manifest, observer_schema, response
):
    """Together with :func:``update_last_applied_manifest_dict_from_resp``, this
    function is called recursively to update a partial ``last_applied_manifest``
    from a partial Kubernetes response

    Args:
        last_applied_manifest (list): partial ``last_applied_manifest`` being
            updated
        observer_schema (list): partial ``observer_schema``
        response (list): partial response from the Kubernetes API.

    This function go through all observed fields, and initialized their value in
    last_applied_manifest if they are not yet present

    """
    # Helper to determine if a value is a scalar (not list or dict)
    def _is_scalar(x):
        return not isinstance(x, (list, dict))

    if not isinstance(observer_schema, list):
        # nothing to do if schema is not a list
        return

    # Ensure last_applied_manifest is a list
    if not isinstance(last_applied_manifest, list):
        raise TypeError("last_applied_manifest must be a list")
    # Ensure response is a list
    if not isinstance(response, list):
        raise TypeError("response must be a list")

    for idx, subschema in enumerate(observer_schema):
        # Skip out-of-range responses
        if idx >= len(response):
            continue
        resp_val = response[idx]

        # Extend last_applied_manifest list if necessary
        while len(last_applied_manifest) <= idx:
            last_applied_manifest.append(None)

        curr_val = last_applied_manifest[idx]

        # Determine how to handle the subschema
        if isinstance(subschema, dict):
            # Expected a nested dict; ensure it's a dict
            if curr_val is None:
                curr_val = {}
                last_applied_manifest[idx] = curr_val
            if not isinstance(curr_val, dict):
                # Incompatible type, skip updating this branch
                continue
            # Use the sibling dict update function
            try:
                # Assume update_last_applied_manifest_dict_from_resp is defined
                update_last_applied_manifest_dict_from_resp(
                    curr_val, subschema, resp_val
                )
            except Exception:
                # If any error, continue to next
                continue
        elif isinstance(subschema, list):
            # Subschema is a list; recurse
            if curr_val is None:
                curr_val = []
                last_applied_manifest[idx] = curr_val
            if not isinstance(curr_val, list):
                # Incompatible type, skip updating this branch
                continue
            update_last_applied_manifest_list_from_resp(
                curr_val, subschema, resp_val
            )
        else:
            # Subschema is a scalar; only set if currently None
            if curr_val is None:
                last_applied_manifest[idx] = resp_val
    # In-place update finishes here. The function modifies last_applied_manifest
    # directly and returns None.'''

def update_last_applied_manifest_dict_from_resp(
    last_applied_manifest, observer_schema, response
):
    """Together with :func:`update_last_applied_manifest_list_from_resp`, this
    function is called recursively to update a partial ``last_applied_manifest``
    from a partial Kubernetes response

    Args:
        last_applied_manifest (dict): partial ``last_applied_manifest`` being
            updated
        observer_schema (dict): partial ``observer_schema``
        response (dict): partial response from the Kubernetes API.

    Raises:
        KeyError: If the observed field is not present in the Kubernetes response
        TypeError: If any of the arguments is not a dictionary

    This function goes through all observed fields, and initializes their value
    in ``last_applied_manifest`` if they are not yet present. It recurses into
    nested dictionaries and delegates list handling to
    :func:`update_last_applied_manifest_list_from_resp`.
    """
    if not isinstance(last_applied_manifest, dict):
        raise TypeError("last_applied_manifest must be a dict")
    if not isinstance(observer_schema, dict):
        raise TypeError("observer_schema must be a dict")
    if not isinstance(response, dict):
        raise TypeError("response must be a dict")

    for field, sub_schema in observer_schema.items():
        if field not in response:
            raise KeyError(f"Missing observed field '{field}' in response")

        # Initialize the field in the last_applied_manifest if it does not exist
        if field not in last_applied_manifest:
            if isinstance(sub_schema, dict):
                last_applied_manifest[field] = {}
            elif isinstance(sub_schema, list):
                last_applied_manifest[field] = []
            else:
                last_applied_manifest[field] = response[field]

        # Recurse into nested structures based on the schema
        if isinstance(sub_schema, dict):
            # If sub_schema is empty (leaf) we keep the value set above
            if sub_schema or isinstance(last_applied_manifest[field], dict):
                update_last_applied_manifest_dict_from_resp(
                    last_applied_manifest[field], sub_schema, response[field]
                )
        elif isinstance(sub_schema, list):
            # Delegate list handling
            if not isinstance(last_applied_manifest[field], list):
                last_applied_manifest[field] = []
            update_last_applied_manifest_list_from_resp(
                last_applied_manifest[field], sub_schema, response[field]
            )
    return

def generate_default_observer_schema(app):
    """Generate the default observer schema for each Kubernetes resource present in
    ``spec.manifest`` for which a custom observer schema hasn't been specified.

    Args:
        app (krake.data.kubernetes.Application): The application for which to generate a
            default observer schema
    """
    if app is None:
        raise ValueError("app must not be None")

    # Safely retrieve the manifest and observer_schema from the app spec.
    # We support both attribute and dict access styles.
    def _get_attr_or_key(container, key):
        if isinstance(container, dict):
            return container.get(key)
        return getattr(container, key, None)

    try:
        spec = getattr(app, "spec", None)
    except Exception:
        spec = None

    if spec is None:
        # No spec configured; nothing to do.
        return {}

    manifest = _get_attr_or_key(spec, "manifest")
    if manifest is None:
        # No manifest provided; nothing to do.
        return {}

    # `observer_schema` may not exist; create an empty dict if so.
    observer_schema = _get_attr_or_key(spec, "observer_schema") or {}

    # Ensure manifest is iterable: dict mapping resource names to objects.
    if not isinstance(manifest, dict):
        raise TypeError("app.spec.manifest should be a dict of resource names to resource definitions")

    # Iterate over resources and create defaults where missing.
    for res_name, res_obj in manifest.items():
        if res_name not in observer_schema:
            # Build a very minimal JSON‑Schema that includes the metadata fields `name`
            # and `namespace`.  This is the default shape that most observers will
            # need to match against.
            default_schema = {
                "metadata": {
                    "type": "object",
                    "properties": {
                        "name": {"type": "string"},
                        "namespace": {"type": "string"}
                    },
                    "required": ["name"]
                }
            }
            observer_schema[res_name] = default_schema

    return observer_schema

def status_str(self, prefix=''):
    """Return string of validator status, with optional prefix."""
    status = getattr(self, 'status', None)
    if status is None:
        return prefix
    try:
        # If status is an Enum or has a 'name' attribute, use it
        s = status.name if hasattr(status, 'name') else str(status)
    except Exception:
        s = str(status)
    return f"{prefix}{s}"

def status_str(self, prefix=''):
    """Return string representation of validation log, with optional prefix."""
    # Attempt to retrieve a log or status attribute from the instance
    log = None
    if hasattr(self, 'validation_log'):
        log = getattr(self, 'validation_log')
    elif hasattr(self, 'log'):
        log = getattr(self, 'log')
    elif hasattr(self, 'status'):
        log = getattr(self, 'status')
    else:
        # No recognizable log attribute; return empty prefix
        return prefix

    try:
        # If the log is already a string, simply return it
        if isinstance(log, str):
            return f"{prefix}{log}"
        # If it is iterable, convert each element to string
        if hasattr(log, '__iter__') and not isinstance(log, (bytes, bytearray)):
            lines = [str(item) for item in log]
            return f"{prefix}{'\n'.join(lines)}"
        # Fallback: cast to string
        return f"{prefix}{str(log)}"
    except Exception as exc:
        # In case of any unexpected error, return prefix followed by error message
        return f"{prefix}Error generating status string: {exc}"

def validate_as_prior_version(self, prior):
    """
    Check that prior is a valid prior version of the current inventory object.

    The input variable prior is also expected to be an InventoryValidator object
    and both self and prior inventories are assumed to have been checked for
    internal consistency.
    """
    errors = []

    # Basic type check
    try:
        import sys
        InventoryValidator = sys.modules[__name__].InventoryValidator
    except Exception:
        InventoryValidator = None
    if InventoryValidator is None:
        errors.append("Could not locate InventoryValidator class in current module")
    elif not isinstance(prior, InventoryValidator):
        errors.append("prior must be an InventoryValidator instance")

    # Compare inventory versioning if the attributes exist
    self_version = getattr(self, "inventory_version", None)
    prior_version = getattr(prior, "inventory_version", None)
    if self_version is None:
        errors.append("Current inventory missing 'inventory_version' attribute")
    if prior_version is None:
        errors.append("Prior inventory missing 'inventory_version' attribute")
    if self_version is not None and prior_version is not None:
        try:
            if prior_version >= self_version:
                errors.append(
                    f"Prior version ({prior_version}) is not older than "
                    f"current version ({self_version})"
                )
        except Exception as exc:
            errors.append(f"Comparison of inventory_version failed: {exc}")

    # Ensure prior inventory items are a subset of current
    self_inventory = getattr(self, "inventory", {})
    prior_inventory = getattr(prior, "inventory", {})
    if not isinstance(self_inventory, dict):
        errors.append("Current inventory's 'inventory' attribute must be a dict")
    if not isinstance(prior_inventory, dict):
        errors.append("Prior inventory's 'inventory' attribute must be a dict")
    if isinstance(self_inventory, dict) and isinstance(prior_inventory, dict):
        for key, prim_val in prior_inventory.items():
            if key not in self_inventory:
                errors.append(f"Key {key!r} in prior inventory is missing from current inventory")
            else:
                curr_val = self_inventory[key]
                if curr_val != prim_val:
                    errors.append(
                        f"Value for key {key!r} differs between current ({curr_val!r}) "
                        f"and prior ({prim_val!r}) inventories"
                    )

    if errors:
        raise ValueError("Prior inventory validation failed: " + "; ".join(errors))
    return True

def get_logical_path_map(inventory, version):
    """Get a map of logical paths in state to files on disk for version in inventory.

    Returns a dictionary: logical_path_in_state -> set(content_files)

    The set of content_files may includes references to duplicate files in
    later versions than the version being described.
    """
    if inventory is None:
        raise ValueError("inventory must not be None")
    if version is None:
        raise ValueError("version must not be None")

    path_map = {}

    try:
        # inventory is expected to be an iterable of mappings
        for item in inventory:
            try:
                # Ensure the item is a mapping
                if not isinstance(item, (dict,)):
                    continue

                item_version = item.get("version")
                if item_version != version:
                    continue

                logical_path = item.get("logical_path")
                content_file = item.get("content_file")

                if logical_path is None or content_file is None:
                    continue

                path_set = path_map.setdefault(logical_path, set())
                path_set.add(content_file)

            except Exception:
                # Skip any malformed entries
                continue
    except TypeError:
        raise ValueError("inventory must be an iterable of mapping objects")

    return path_map

def validate_fixity(self, fixity, manifest_files):
    """Validate fixity block in inventory.

    Check the structure of the fixity block and makes sure that only files
    listed in the manifest are referenced.
    """
    if not fixity:
        # Empty or None is acceptable; nothing to validate
        return

    if not isinstance(fixity, dict):
        raise ValueError(f"Fixity block must be a dict, got {type(fixity).__name__}")

    # Allow optional top‑level keys that are not file references
    known_keys = {"algorithm", "files"}
    # If the structure follows the pattern {"algorithm": "...", "files": {...}}
    if "files" in fixity:
        # Normalise to the dictionary of per‑file metadata
        files_meta = fixity["files"]
    else:
        files_meta = fixity

    if not isinstance(files_meta, dict):
        raise ValueError("The 'files' entry in the fixity block must be a dict")

    for fname, meta in files_meta.items():
        if fname not in manifest_files:
            raise ValueError(f"Fixity references unknown file '{fname}'")
        if not isinstance(meta, dict):
            raise ValueError(f"Metadata for file '{fname}' must be a dict, got {type(meta).__name__}")

        # Common expected keys; adjust as necessary
        required_keys = {"hash", "size"}
        missing = required_keys - meta.keys()
        if missing:
            raise ValueError(f"Metadata for file '{fname}' missing required key(s): {', '.join(sorted(missing))}")

        if not isinstance(meta["hash"], str):
            raise ValueError(f"Hash for file '{fname}' must be a string")
        if not isinstance(meta["size"], int):
            raise ValueError(f"Size for file '{fname}' must be an integer")

    # If the block contains keys besides known ones or file entries, ensure they're valid
    for key in fixity.keys() - known_keys:
        if key == "files":
            continue
        # Unexpected top‑level key
        raise ValueError(f"Unexpected key in fixity block: '{key}'")
    return

def files_list(path):
    """
    Return the files in `path`
    """
    abs_path = os.path.abspath(path)
    if not os.path.exists(abs_path):
        raise FileNotFoundError(f"No such file or directory: '{path}'")
    if os.path.isfile(abs_path):
        return [abs_path]
    if os.path.isdir(abs_path):
        try:
            return [
                os.path.join(abs_path, entry)
                for entry in os.listdir(abs_path)
                if os.path.isfile(os.path.join(abs_path, entry))
            ]
        except OSError as e:
            raise e
    raise ValueError(f"Unsupported path type: '{path}'")

def _explore_folder(folder):
    """
    Get packages' data from folder

    Groups files by their XML basename and returns data in dict format.

    Parameters
    ----------
    folder : str
        Folder of the package
    Returns
    -------
    dict
    """
    import os

    if not isinstance(folder, str):
        raise TypeError("folder must be a string path")
    if not os.path.isdir(folder):
        raise ValueError(f"Provided folder does not exist or is not a directory: {folder}")

    packages = {}
    xml_bases = set()

    # First pass: discover all XML files and initialize groups
    for root, _, files in os.walk(folder):
        for filename in files:
            if filename.lower().endswith('.xml'):
                base = os.path.splitext(filename)[0]
                xml_bases.add(base)
                rel_path = os.path.relpath(os.path.join(root, filename), folder)
                packages.setdefault(base, []).append(rel_path)

    # Second pass: add non-XML files that share an XML basename
    for root, _, files in os.walk(folder):
        for filename in files:
            if filename.lower().endswith('.xml'):
                continue
            base = os.path.splitext(filename)[0]
            if base in xml_bases:
                rel_path = os.path.relpath(os.path.join(root, filename), folder)
                packages[base].append(rel_path)

    # Optional: sort files within each package for deterministic output
    for base in packages:
        packages[base] = sorted(packages[base])

    return packages

def files_list_from_zipfile(zip_path):
    """Return the files in `zip_path`."""
    try:
        import zipfile
        with zipfile.ZipFile(zip_path, 'r') as zf:
            # Filter out directory entries (ending with '/') and optional .pyc files
            return [name for name in zf.namelist()
                    if not name.endswith('/') and not name.endswith('.pyc')]
    except FileNotFoundError:
        raise FileNotFoundError(f"Zip file not found: {zip_path}")
    except zipfile.BadZipFile:
        raise zipfile.BadZipFile(f"Cannot read zip file: {zip_path}")

def fix_namespace_prefix_w(content):
    """Convert os textos cujo padrão é `w:st="` em `w-st="`"""
    if not isinstance(content, str):
        raise TypeError("content must be a string")
    return content.replace('w:st="', 'w-st="')

def match_pubdate(node, pubdate_xpaths):
    """
    Retorna o primeiro match da lista de pubdate_xpaths
    """
    if node is None:
        return None

    # Accept a single xpath string or a sequence
    if isinstance(pubdate_xpaths, str):
        pubdate_xpaths = [pubdate_xpaths]
    elif not hasattr(pubdate_xpaths, '__iter__'):
        return None

    for xpath in pubdate_xpaths:
        try:
            matches = node.xpath(xpath)
        except Exception:
            # Skip invalid xpath expressions or nodes that don't support xpath
            continue
        if matches:
            return matches[0]

    return None

def pretty(self, indent=0, debug=False):
    """
    Return a pretty formatted representation of self.

    Args:
        indent (int, optional): The indentation level for output. Default is 0.
        debug (bool, optional): If True, return the raw repr of the object.
            Otherwise, attempt a human‑readable JSON or pprint representation.

    Returns:
        str: A string containing a pretty printed representation of ``self``.
    """
    if debug:
        return repr(self)

    # Try to serialize using json; this works well for dicts, lists, tuples, etc.
    try:
        import json

        def _default(o):
            try:
                return o.__dict__
            except Exception:
                # Fallback to str for complex objects
                return str(o)

        # Ensure indent is a non‑negative integer
        _indent = max(int(indent), 0) if indent is not None else None
        return json.dumps(self, default=_default, indent=_indent, sort_keys=True)
    except Exception:
        pass

    # Fall back to pprint if json fails.
    try:
        import pprint
        return pprint.pformat(self, indent=indent)
    except Exception:
        # As a last resort, return repr.
        return repr(self)

def absorb(self, args):
    """
    Given an `args` sequence of expressions, return a new list of expression
    applying absorption and negative absorption.

    See https://en.wikipedia.org/wiki/Absorption_law

    Absorption::

        A & (A | B) = A, A | (A & B) = A

    Negative absorption::

        A & (~A | B) = A & B, A | (~A & B) = A | B
    """
    try:
        import sympy
    except ImportError:
        # Fallback: if sympy is not available, return the original list.
        return list(args)

    result = []
    for expr in args:
        # Prepare a sympy expression from the input, if it is a string.
        expr_sym = expr
        try:
            if isinstance(expr, str):
                expr_sym = sympy.sympify(expr)
        except Exception:
            # If parsing fails, keep original.
            expr_sym = expr

        try:
            simplified = sympy.simplify(expr_sym)
        except Exception:
            # If simplification fails, keep original.
            simplified = expr

        result.append(simplified)

    return result

def tzname_in_python2(namefunc):
    """Change unicode output into bytestrings in Python 2

    tzname() API changed in Python 3. It used to return bytes, but was changed
    to unicode strings
    """
    def wrapper(*args, **kwargs):
        result = namefunc(*args, **kwargs)
        import sys
        if sys.version_info[0] >= 3:
            return result
        else:
            # In Python 2, unicode type is called 'unicode'
            try:
                unicode_type = unicode
            except NameError:
                unicode_type = str  # fallback, unlikely
            if isinstance(result, unicode_type):
                return result.encode()
            return result
    return wrapper

def get_versions():
    """Get version information or return default if unable to do so."""
    try:
        with open('version.py', 'r') as f:
            for line in f:
                if "__version__" in line:
                    _, val = line.split('=', 1)
                    val = val.strip()
                    if val[0] in ("'", '"') and val[-1] == val[0]:
                        val = val[1:-1]
                    return val
    except Exception:
        pass
    return 'unknown'

def render(pieces, style):
    """Render the given version pieces into the requested style."""
    if pieces is None:
        pieces = {}
    style = style.lower() if isinstance(style, str) else ''

    try:
        if style in ('json',):
            try:
                import json
            except ImportError:
                raise RuntimeError('JSON support requires the json module')
            return json.dumps(pieces, indent=2, sort_keys=True)
        elif style in ('yaml', 'yml'):
            try:
                import yaml
            except ImportError:
                # Fallback to JSON if PyYAML is not available
                import json
                return json.dumps(pieces, indent=2, sort_keys=True)
            return yaml.safe_dump(pieces, default_flow_style=False)
        elif style in ('text', 'plain'):
            if isinstance(pieces, dict):
                lines = [f'{k}: {v}' for k, v in pieces.items()]
            elif isinstance(pieces, (list, tuple)):
                lines = [str(item) for item in pieces]
            else:
                lines = [str(pieces)]
            return '\n'.join(lines)
        elif style in ('html', 'htm'):
            if isinstance(pieces, dict):
                items = ''.join(f'<li><strong>{k}</strong>: {v}</li>'
                                for k, v in pieces.items())
            elif isinstance(pieces, (list, tuple)):
                items = ''.join(f'<li>{item}</li>' for item in pieces)
            else:
                items = f'<li>{pieces}</li>'
            return f'<ul>{items}</ul>'
        elif style in ('csv',):
            try:
                import csv
                from io import StringIO
            except ImportError:
                raise RuntimeError('CSV support requires the csv module')
            output = StringIO()
            if isinstance(pieces, dict):
                writer = csv.writer(output)
                writer.writerow(pieces.keys())
                writer.writerow(pieces.values())
            elif isinstance(pieces, (list, tuple)):
                writer = csv.writer(output)
                writer.writerows(pieces)
            else:
                writer = csv.writer(output)
                writer.writerow([pieces])
            return output.getvalue()
        else:
            raise ValueError(f'Unsupported style "{style}". '
                             'Supported styles are: json, yaml, text, html, csv.')
    except Exception as exc:
        raise RuntimeError(f'Error rendering pieces to style "{style}": {exc}') from exc

def plus_or_dot(pieces):
    """Return a + if we don't already have one, else return a ."""
    # Handle simple string input
    if isinstance(pieces, str):
        return '.' if '+' in pieces else '+'

    # If pieces is None or not iterable, default to returning '+'
    try:
        iterator = iter(pieces)
    except TypeError:
        return '+'

    # Check if any element contains a '+'
    has_plus = False
    for elem in iterator:
        if elem is None:
            continue
        try:
            if '+' in str(elem):
                has_plus = True
                break
        except Exception:
            # If conversion fails, skip this element
            continue

    return '.' if has_plus else '+'

def validate_hierarchy(self, validate_objects=True, check_digests=True, show_warnings=False):
        """Validate storage root hierarchy.

        Returns:
            num_objects - number of objects checked
            good_objects - number of objects checked that were found to be valid
        """
        num_objects = 0
        good_objects = 0

        # Attempt to gather objects from the storage root
        objects = []
        try:
            # Prefer a dedicated method if available
            objects = list(self.storage_root.list_objects())
        except AttributeError:
            # Fallback: assume storage_root is iterable
            try:
                objects = list(self.storage_root)
            except Exception:
                objects = []

        for obj in objects:
            num_objects += 1
            is_valid = True

            # Individual object validation
            if validate_objects:
                if hasattr(obj, "validate"):
                    try:
                        obj.validate()
                    except Exception as exc:
                        is_valid = False
                        if show_warnings:
                            print(f"Warning: object {obj} failed validation: {exc}")
                else:
                    if show_warnings:
                        print(f"Warning: object {obj} has no 'validate' method; skipping validation")

            # Digest checking
            if check_digests and hasattr(obj, "check_digest"):
                try:
                    if not obj.check_digest():
                        is_valid = False
                        if show_warnings:
                            print(f"Warning: object {obj} digest mismatch")
                except Exception as exc:
                    is_valid = False
                    if show_warnings:
                        print(f"Warning: object {obj} digest check raised exception: {exc}")

            if is_valid:
                good_objects += 1

        return num_objects, good_objects

def initialize(self):
        """Create and initialize a new OCFL storage root."""
        import os
        import json
        import traceback
        # Determine the root path; it must be set on the instance.
        root = getattr(self, "root", None)
        if not isinstance(root, str) or not root:
            raise AttributeError("Storage root path ('root' attribute) is not set on the instance.")
        try:
            # If the root already exists, ensure it is empty; otherwise raise.
            if os.path.exists(root):
                if os.listdir(root):
                    raise RuntimeError(f"OCFL root '{root}' already exists and is not empty.")
            else:
                os.makedirs(root, exist_ok=True)
            # Create required subdirectories.
            for sub in ("objects", "metadata"):
                sub_path = os.path.join(root, sub)
                os.makedirs(sub_path, exist_ok=True)
            # Create an initial manifest file if it does not exist.
            manifest_path = os.path.join(root, "manifest.json")
            if not os.path.exists(manifest_path):
                manifest_data = {
                    "ocfl_version": "2.0",
                    "created_at": os.path.getmtime(root)
                }
                with open(manifest_path, "w", encoding="utf-8") as f:
                    json.dump(manifest_data, f, indent=2)
            # Store the root back on the instance for future reference.
            self.root = root
            return root
        except Exception as exc:
            # Provide a clear message and preserve the traceback.
            raise RuntimeError(f"Failed to initialize OCFL storage root at '{root}'.") from exc

def next_version(version):
    """Next version identifier following existing pattern.

    Must deal with both zero-prefixed and non-zero prefixed versions.
    """
    if not isinstance(version, str) or not version:
        return ""
    if not version.isdigit():
        return ""
    width = len(version)
    try:
        next_num = int(version, 10) + 1
    except ValueError:
        return ""
    next_str = str(next_num)
    if len(next_str) < width:
        next_str = next_str.rjust(width, '0')
    return next_str

def validate_version_inventories(self, version_dirs):
    """Each version SHOULD have an inventory up to that point.

    Also keep a record of any content digests different from those in the root inventory
    so that we can also check them when validating the content.

    version_dirs is an array of version directory names and is assumed to be in
    version sequence (1, 2, 3...).
    """
    # Basic input validation
    if not isinstance(version_dirs, (list, tuple)):
        raise TypeError("version_dirs must be a list or tuple of directory paths")
    if not version_dirs:
        raise ValueError("No version directories provided")

    # Load the root inventory (first directory) as the baselines
    root_dir = version_dirs[0]
    root_inv_path = os.path.join(root_dir, "inventory.json")
    if not os.path.isfile(root_inv_path):
        raise FileNotFoundError(f"Root inventory file not found: {root_inv_path}")
    try:
        with open(root_inv_path, "r") as f:
            root_inventory = json.load(f)
    except Exception as exc:
        raise ValueError(f"Failed to parse root inventory at {root_inv_path}") from exc

    if not isinstance(root_inventory, dict):
        raise ValueError(f"Root inventory must contain a JSON object mapping file paths to digests")

    # Prepare structures for validation
    self.different_digests = {}  # {file_path: {version_dir: digest, ...}}
    previous_keys = set(root_inventory.keys())
    previous_inventory = root_inventory

    # Iterate through each version directory, ensuring inventories are cumulative
    for idx, vdir in enumerate(version_dirs):
        inv_path = os.path.join(vdir, "inventory.json")
        if not os.path.isfile(inv_path):
            raise FileNotFoundError(f"Inventory file missing in version directory: {vdir}")

        try:
            with open(inv_path, "r") as f:
                inv = json.load(f)
        except Exception as exc:
            raise ValueError(f"Failed to load inventory in {vdir}") from exc

        if not isinstance(inv, dict):
            raise ValueError(f"Inventory in {vdir} must be a JSON object")

        # Ensure the inventory includes all files from the previous version (cumulative)
        if idx > 0:
            missing_in_prev = previous_keys - inv.keys()
            if missing_in_prev:
                missing_str = ", ".join(sorted(missing_in_prev))
                raise ValueError(f"Inventory in {vdir} missing files from previous version: {missing_str}")

        # Record any digests that differ from the root inventory
        for file_path, digest in inv.items():
            if file_path in root_inventory and digest != root_inventory[file_path]:
                self.different_digests.setdefault(file_path, {})[vdir] = digest

        # Update previous state for the next iteration
        previous_keys = set(inv.keys())
        previous_inventory = inv

    return self

def find_path_type(path):
    """
    Return a string indicating the type of thing at the given path.

    Return values:
        'root'    - looks like an OCFL Storage Root
        'object'  - looks like an OCFL Object
        'file'    - a file, might be an inventory
        other string explains error description

    Looks only at "0=*" Namaste files to determine the directory type.
    """
    import os

    # Basic sanity checks
    if not path:
        return "error: path is empty or None"

    # Resolve to absolute path to avoid issues with relative symlinks
    try:
        abs_path = os.path.abspath(path)
    except (TypeError, OSError) as exc:
        return f"error: could not resolve absolute path: {exc}"

    if not os.path.exists(abs_path):
        return f"error: path does not exist: {abs_path}"

    # If the path is a regular file (or a symlink to a file)
    try:
        if os.path.isfile(abs_path):
            return "file"
    except OSError as exc:
        return f"error: could not determine if path is a file: {exc}"

    # If the path is a directory (or a symlink to a directory)
    try:
        if os.path.isdir(abs_path):
            # List directory contents; handle permission issues gracefully
            try:
                items = os.listdir(abs_path)
            except PermissionError as exc:
                return f"error: permission denied when reading directory: {exc}"
            except OSError as exc:
                return f"error: could not list directory contents: {exc}"

            # Check for any "0=" Namaste files
            namaste_files = [name for name in items if name.startswith("0=")]
            if namaste_files:
                return "object"
            else:
                # No Namaste files so consider it a storage root
                return "root"
    except OSError as exc:
        return f"error: could not determine if path is a directory: {exc}"

    # If we reach here the path is neither file nor directory
    return f"error: unknown path type: {abs_path}"

def amend_bzparams(self, params, bug_ids):
    """Amend the Bugzilla params"""
    if not isinstance(params, dict):
        raise ValueError("The first argument 'params' must be a dictionary")
    # Normalise bug_ids into a list
    if isinstance(bug_ids, (int, str)):
        bug_id_list = [bug_ids]
    elif isinstance(bug_ids, (list, tuple)):
        bug_id_list = list(bug_ids)
    else:
        raise ValueError("bug_ids must be an int, str, list, or tuple")
    # Convert all items to strings (Bugzilla expects integer IDs as strings)
    bug_id_strs = [str(b) for b in bug_id_list]
    if not bug_id_strs:
        # nothing to add
        return
    # If 'id' already exists, append the new ids separated by commas
    existing = params.get("id")
    if existing:
        # ensure existing is a string
        if isinstance(existing, list):
            existing = ",".join(map(str, existing))
        elif not isinstance(existing, str):
            existing = str(existing)
        params["id"] = ",".join([existing] + bug_id_strs)
    else:
        # single id or comma‑separated string
        params["id"] = ",".join(bug_id_strs) if len(bug_id_strs) > 1 else bug_id_strs[0]
    # The method mutates the dictionary in place and returns None
    return None

def deep_merge_nodes(nodes):
    '''
    Given a nested borgmatic configuration data structure as a list of tuples in the form of:

        (
            ruamel.yaml.nodes.ScalarNode as a key,
            ruamel.yaml.nodes.MappingNode or other Node as a value,
        ),

    ... deep merge any node values corresponding to duplicate keys and return the result. If
    there are colliding keys with non-MappingNode values (e.g., integers or strings), the last
    of the values wins.

    For instance, given node values of:

        [
            (
                ScalarNode(tag='tag:yaml.org,2002:str', value='retention'),
                MappingNode(tag='tag:yaml.org,2002:map', value=[
                    (
                        ScalarNode(tag='tag:yaml.org,2002:str', value='keep_hourly'),
                        ScalarNode(tag='tag:yaml.org,2002:int', value='24')
                    ),
                    (
                        ScalarNode(tag='tag:yaml.org,2002:str', value='keep_daily'),
                        ScalarNode(tag='tag:yaml.org,2002:int', value='7')
                    ),
                ]),
            ),
            (
                ScalarNode(tag='tag:yaml.org,2002:str', value='retention'),
                MappingNode(tag='tag:yaml.org,2002:map', value=[
                    (
                        ScalarNode(tag='tag:yaml.org,2002:str', value='keep_daily'),
                        ScalarNode(tag='tag:yaml.org,2002:int', value='5')
                    ),
                ]),
            ),
        ]

    ... the returned result would be:

        [
            (
                ScalarNode(tag='tag:yaml.org,2002:str', value='retention'),
                MappingNode(tag='tag:yaml.org,2002:map', value=[
                    (
                        ScalarNode(tag='tag:yaml.org,2002:str', value='keep_hourly'),
                        ScalarNode(tag='tag:yaml.org,2002:int', value='24')
                    ),
                    (
                        ScalarNode(tag='tag:yaml.org,2002:str', value='keep_daily'),
                        ScalarNode(tag='tag:yaml.org,2002:int', value='5')
                    ),
                ]),
            ),
        ]

    The purpose of deep merging like this is to support, for instance, merging one borgmatic
    configuration file into another for reuse, such that a configuration section ("retention",
    etc.) does not completely replace the corresponding section in a merged file.
    '''
    if not isinstance(nodes, list):
        raise TypeError('Expected a list of node tuples')
    # Helper to determine if a node is a MappingNode by checking its tag
    def _is_mapping(node):
        return getattr(node, 'tag', None) in (None, 'tag:yaml.org,2002:map')
    # Recursive merge of mapping node values
    def _merge_mapping(node1, node2):
        # Both nodes should be mapping nodes
        if not (_is_mapping(node1) and _is_mapping(node2)):
            return node2
        merged_pairs = _merge_pairs(node1.value + node2.value)
        # Preserve original node type
        return type(node1)(node1.tag, merged_pairs)
    # Merge a list of (key_node, val_node) pairs
    def _merge_pairs(pairs):
        seen = {}
        order = []
        for key_node, val_node in pairs:
            key_val = getattr(key_node, 'value', None)
            if key_val not in seen:
                seen[key_val] = (key_node, val_node)
                order.append(key_val)
            else:
                old_key_node, old_val_node = seen[key_val]
                if _is_mapping(old_val_node) and _is_mapping(val_node):
                    merged_val = _merge_mapping(old_val_node, val_node)
                    seen[key_val] = (old_key_node, merged_val)
                else:
                    seen[key_val] = (old_key_node, val_node)  # last wins
        return [(seen[k][0], seen[k][1]) for k in order]
    return _merge_pairs(nodes)

def parse_arguments(*arguments):
    '''
    Given command-line arguments with which this script was invoked, parse the arguments and return
    them as an ArgumentParser instance.
    '''
    import argparse
    import sys

    parser = argparse.ArgumentParser(description="Script command-line arguments")
    # The parser can be extended by downstream code if needed.
    # If no arguments are provided explicitly, default to sys.argv[1:].
    try:
        if arguments:
            return parser.parse_args(arguments)
        else:
            return parser.parse_args()
    except Exception as e:
        # Provide a clear error message while preserving the original exception context.
        raise ValueError(f"Argument parsing failed: {e}") from e

def parser_flags(parser):
    """
    Given an argparse.ArgumentParser instance, return its argument flags in a space-separated
    string.
    """
    # Collect all option strings from the parser's actions, preserving order
    flags = []
    seen = set()
    try:
        actions = getattr(parser, "_actions", [])
    except Exception:
        # If parser doesn't have _actions attribute, return empty string
        return ""

    for action in actions:
        option_strings = getattr(action, "option_strings", [])
        for opt in option_strings:
            if opt and opt not in seen:
                flags.append(opt)
                seen.add(opt)

    return " ".join(flags)

def deep_merge_nodes(nodes):
    '''
    Given a nested borgmatic configuration data structure as a list of tuples in the form of:

        (
            ruamel.yaml.nodes.ScalarNode as a key,
            ruamel.yaml.nodes.MappingNode or other Node as a value,
        ),

    ... deep merge any node values corresponding to duplicate keys and return the result. If
    there are colliding keys with non-MappingNode values (e.g., integers or strings), the last
    of the values wins.

    For instance, given node values of:

        [
            (
                ScalarNode(tag='tag:yaml.org,2002:str', value='retention'),
                MappingNode(tag='tag:yaml.org,2002:map', value=[
                    (
                        ScalarNode(tag='tag:yaml.org,2002:str', value='keep_hourly'),
                        ScalarNode(tag='tag:yaml.org,2002:int', value='24')
                    ),
                    (
                        ScalarNode(tag='tag:yaml.org,2002:str', value='keep_daily'),
                        ScalarNode(tag='tag:yaml.org,2002:int', value='7')
                    ),
                ]),
            ),
            (
                ScalarNode(tag='tag:yaml.org,2002:str', value='retention'),
                MappingNode(tag='tag:yaml.org,2002:map', value=[
                    (
                        ScalarNode(tag='tag:yaml.org,2002:str', value='keep_daily'),
                        ScalarNode(tag='tag:yaml.org,2002:int', value='5')
                    ),
                ]),
            ),
        ]

    ... the returned result would be:

        [
            (
                ScalarNode(tag='tag:yaml.org,2002:str', value='retention'),
                MappingNode(tag='tag:yaml.org,2002:map', value=[
                    (
                        ScalarNode(tag='tag:yaml.org,2002:str', value='keep_hourly'),
                        ScalarNode(tag='tag:yaml.org,2002:int', value='24')
                    ),
                    (
                        ScalarNode(tag='tag:yaml.org,2002:str', value='keep_daily'),
                        ScalarNode(tag='tag:yaml.org,2002:int', value='5')
                    ),
                ]),
            ),
        ]

    The purpose of deep merging like this is to support, for instance, merging one borgmatic
    configuration file into another for reuse, such that a configuration section ("retention",
    etc.) does not completely replace the corresponding section in a merged file.
    '''
    from ruamel.yaml.nodes import MappingNode, ScalarNode

    def merge_mapping_node(base, new):
        """
        Recursively merge two MappingNodes. The `new` MappingNode is merged into `base`.
        The resulting MappingNode preserves the order of keys in `base`; new keys are
        appended at the end.
        """
        result_pairs = list(base.value)  # start with base's pairs
        for key_new, val_new in new.value:
            found = False
            for idx, (key_base, val_base) in enumerate(result_pairs):
                if key_base.value == key_new.value:
                    found = True
                    if isinstance(val_base, MappingNode) and isinstance(val_new, MappingNode):
                        # Deep merge
                        result_pairs[idx] = (key_base, merge_mapping_node(val_base, val_new))
                    else:
                        # New value wins
                        result_pairs[idx] = (key_base, val_new)
                    break
            if not found:
                result_pairs.append((key_new, val_new))
        return MappingNode(tag=base.tag, value=result_pairs)

    merged_order = []          # list of key strings preserving first appearance
    merged_entries = {}        # key string -> (key_node, value_node)

    for key_node, value_node in nodes:
        if not isinstance(key_node, ScalarNode):
            # If key is not a ScalarNode, treat it as unique and just keep first
            key_id = object()
        else:
            key_id = key_node.value

        if key_id in merged_entries:
            existing_key_node, existing_val_node = merged_entries[key_id]
            if isinstance(existing_val_node, MappingNode) and isinstance(value_node, MappingNode):
                merged_val = merge_mapping_node(existing_val_node, value_node)
                merged_entries[key_id] = (existing_key_node, merged_val)
            else:
                # New value overrides
                merged_entries[key_id] = (key_node, value_node)
        else:
            merged_entries[key_id] = (key_node, value_node)
            merged_order.append(key_id)

    # Reconstruct list of tuples in the order of first appearance
    result = []
    for key_id in merged_order:
        key_node, val_node = merged_entries[key_id]
        result.append((key_node, val_node))

    return result.

def parser_flags(parser):
    '''
    Given an argparse.ArgumentParser instance, return its argument flags in a space-separated
    string.
    '''
    try:
        flags = set()
        for action in parser._actions:
            for opt in action.option_strings:
                flags.add(opt)
        # Sort the flags to produce a deterministic order
        sorted_flags = sorted(flags)
        return ' '.join(sorted_flags)
    except AttributeError as e:
        raise TypeError("parser must be an argparse.ArgumentParser instance") from e

def bash_completion():
    '''
    Return a bash completion script for the borgmatic command. Produce this by introspecting
    borgmatic's command-line argument parsers.
    '''
    try:
        import borgmatic
        from click import Command
        from click import get_current_context as click_context
        # Attempt to import click's completion utilities if available
        try:
            from click_completion import register_completer
        except Exception:
            register_completer = None

        # Retrieve the root click command (normally exposed as borgmatic.__main__ or borgmatic.main.cli)
        root_command = None
        for attr in ('__main__', 'main', 'cli'):
            if hasattr(borgmatic, attr):
                candidate = getattr(borgmatic, attr)
                if isinstance(candidate, Command):
                    root_command = candidate
                    break
        if root_command is None:
            return ''

        # If click-completion is available, use it to generate a bash script
        if register_completer and hasattr(root_command, 'shell_completion'):
            # Using the latest API (click 8.1+)
            script = root_command.shell_completion('bash')
            if script:
                return script

        # Fallback: manually generate a simple bash completion script
        # that calls 'borgmatic [arguments] --help' to discover options.
        # We parse the help output to extract flags and subcommands.
        import subprocess, re, textwrap
        cmd = [sys.executable, '-m', 'borgmatic', '--help']
        try:
            help_output = subprocess.check_output(cmd, text=True, encoding='utf8')
        except Exception:
            return ''

        flags = set()
        subcmds = set()
        for line in help_output.splitlines():
            # Lines that start with one or more spaces followed by '--' or '-' are options
            if re.match(r'^\s{2,}', line):
                parts = line.split()
                for part in parts:
                    if part.startswith('-'):
                        flags.add(part.split(',')[0])
            # Subcommands are often after the description
            elif re.match(r'^\s{2,}', line) and not any(part.startswith('-') for part in line.split()):
                subcmds.add(line.strip().split()[0])
        # Build the bash completion function
        bash_func = textwrap.dedent(f'''
        _borgmatic_completion()
        {{
            local cur prev words cword
            _init_completion || return
            if [[ $cword -eq 1 ]]; then
                COMPREPLY=($(compgen -W "{" ".join(subcmds)}" -- "$cur"))
                return
            fi
            case "${{prev}}" in
                {" | ".join(f'"{f}"' for f in flags)}
                    ;;
                *)
                    COMPREPLY=($(compgen -W "{" ".join(flags)}" -- "$cur"))
                    ;;
            esac
        }}
        complete -F _borgmatic_completion borgmatic
        ''')
        return bash_func.strip()
    except Exception:
        # On any failure, return an empty string
        return ''

def parse_subparser_arguments(unparsed_arguments, subparsers):
    '''
    Given a sequence of arguments and a dict from subparser name to argparse.ArgumentParser
    instance, give each requested action's subparser a shot at parsing all arguments. This
    allows common arguments like "--repository" to be shared across multiple subparsers.

    Return the result as a tuple of (a dict mapping from subparser name to a parsed namespace of
    arguments, a list of remaining arguments not claimed by any subparser).
    '''
    # Validate inputs
    if subparsers is None:
        subparsers = {}
    if not isinstance(subparsers, dict):
        raise TypeError(
            f"subparsers must be a dict mapping names to ArgumentParser instances, got {type(subparsers).__name__}")

    input_args = list(unparsed_arguments) if unparsed_arguments is not None else []

    parsed_map = {}
    leftovers_list = []

    for name, parser in subparsers.items():
        if not hasattr(parser, "parse_known_args"):
            raise TypeError(f"subparser for '{name}' must have parse_known_args method, got {type(parser).__name__}")
        try:
            ns, left = parser.parse_known_args(input_args)
        except Exception as exc:
            raise ValueError(f"Error parsing arguments for subparser '{name}'") from exc
        parsed_map[name] = ns
        leftovers_list.append(left)

    # Determine arguments not claimed by any subparser
    if leftovers_list:
        # Preserve order of first leftover while ensuring the argument is present in all leftovers
        remaining = []
        first = leftovers_list[0]
        for arg in first:
            if all(arg in left for left in leftovers_list[1:]):
                remaining.append(arg)
    else:
        remaining = list(input_args)

    return parsed_map, remaining

def paging(response, max_results):
    """
    Returns WAPI response page by page

    Args:
        response (list): WAPI response.
        max_results (int): Maximum number of objects to be returned in one page.
    Returns:
        Generator object with WAPI response split page by page.
    """
    if max_results is None:
        raise ValueError("max_results must not be None")
    try:
        max_results = int(max_results)
    except (TypeError, ValueError):
        raise TypeError("max_results must be an integer")
    if max_results <= 0:
        raise ValueError("max_results must be a positive integer")

    if response is None:
        raise ValueError("response must not be None")

    # Ensure response is iterable
    try:
        iterator = iter(response)
    except TypeError:
        raise TypeError("response must be an iterable (e.g., list)")

    page = []
    for item in iterator:
        page.append(item)
        if len(page) == max_results:
            yield page
            page = []

    if page:
        yield page

def _dictsum(dicts):
    """
    Combine values of the dictionaries supplied by iterable dicts.

    >>> _dictsum([{'a': 1, 'b': 2}, {'a': 5, 'b': 0}])
    {'a': 6, 'b': 2}
    """
    # Validate input
    if dicts is None:
        return {}
    try:
        iterator = iter(dicts)
    except TypeError:
        raise TypeError("Argument must be an iterable of dictionaries")
    result = {}
    for d in iterator:
        if not isinstance(d, dict):
            raise TypeError("All elements of the iterable must be dictionaries")
        for key, val in d.items():
            if key in result:
                try:
                    result[key] += val
                except Exception:
                    # If addition fails (different types), override with the latest value
                    result[key] = val
            else:
                result[key] = val
    return result

def _replace_url_args(url, url_args):
    """Replace any custom string URL items with values in args"""

    if not url:
        return ''

    if not url_args:
        return url

    import re
    import urllib.parse

    # Pattern matches {var} or :var
    pattern = r'\{(?P<var1>[^}]+)\}|\:(?P<var2>[^/]+)'

    def _repl(match):
        var = match.group('var1') or match.group('var2')
        if var not in url_args:
            raise KeyError(f"URL argument '{var}' not provided.")
        value = str(url_args[var])
        # Encode the value for use in a URL path/query
        return urllib.parse.quote(value, safe='')

    try:
        return re.sub(pattern, _repl, url)
    except Exception as exc:
        # In case of any unexpected error, return the original URL
        # and optionally log the error if a logger is available.
        return url

def is_none_string(val):
    """Check if a string represents a None value."""
    try:
        if isinstance(val, str):
            stripped = val.strip().lower()
            # Empty string or common placeholders for None
            return stripped in ('', 'none', 'null')
        return False
    except Exception:
        # In case of any unexpected error, treat as not a None string
        return False

def parser_flags(parser):
    '''
    Given an argparse.ArgumentParser instance, return its argument flags in a space-separated
    string.
    '''
    if parser is None:
        raise ValueError("parser cannot be None")
    try:
        actions = parser._actions
    except AttributeError:
        raise TypeError("Expected an argparse.ArgumentParser instance")
    flags = []
    for action in actions:
        # action.option_strings may not exist on some custom actions
        opt_strings = getattr(action, 'option_strings', [])
        if opt_strings:
            flags.extend(opt_strings)
    return ' '.join(flags)

def vertex3tuple(vertices):
    '''
    return 3 points for each vertex of the polygon. This will include the vertex and the 2 points on both sides of the vertex::

        polygon with vertices ABCD
        Will return
        DAB, ABC, BCD, CDA -> returns 3tuples
        #A    B    C    D  -> of vertices
    '''
    try:
        verts = list(vertices)
    except TypeError:
        raise TypeError("vertices must be an iterable")
    n = len(verts)
    if n < 3:
        return []
    result = []
    for i in range(n):
        result.append((verts[i-1], verts[i], verts[(i+1) % n]))
    return result

def int_to_string(number: int, alphabet: List[str], padding: Optional[int] = None) -> str:
    """
    Convert a number to a string, using the given alphabet.

    The output has the most significant digit first.
    """
    if not isinstance(number, int):
        raise TypeError(f"number must be an int, got {type(number).__name__}")
    if not isinstance(alphabet, list):
        raise TypeError(f"alphabet must be a list, got {type(alphabet).__name__}")
    if not alphabet:
        raise ValueError("alphabet cannot be empty")
    base = len(alphabet)
    if base <= 1:
        raise ValueError("alphabet must contain at least two characters to define a base")

    negative = number < 0
    num = abs(number)

    # Handle zero explicitly; ensure at least one digit
    digits = []
    if num == 0:
        digits.append(alphabet[0])
    else:
        while num:
            num, rem = divmod(num, base)
            digits.append(alphabet[rem])

    # Most significant digit first
    digits.reverse()
    result = ''.join(digits)

    # Apply padding if requested
    if padding is not None:
        if not isinstance(padding, int) or padding < 0:
            raise ValueError(f"padding must be a non‑negative integer, got {padding!r}")
        if len(result) < padding:
            result = alphabet[0] * (padding - len(result)) + result

    if negative:
        result = '-' + result

    return result

def _replace_register(flow_params, register_number, register_value):
    """Replace value from flows to given register number

    'register_value' key in dictionary will be replaced by register number
    given by 'register_number'

    :param flow_params: Dictionary containing defined flows
    :param register_number: The number of register where value will be stored
    :param register_value: Key to be replaced by register number

    """
    if not isinstance(flow_params, dict):
        raise TypeError(f"flow_params must be a dict, got {type(flow_params).__name__}")
    if not isinstance(register_number, int):
        raise TypeError(f"register_number must be an int, got {type(register_number).__name__}")
    if not isinstance(register_value, str):
        raise TypeError(f"register_value must be a str, got {type(register_value).__name__}")

    def _traverse(obj):
        if isinstance(obj, dict):
            for key, value in obj.items():
                if key == register_value:
                    obj[key] = register_number
                else:
                    _traverse(value)
        elif isinstance(obj, list) or isinstance(obj, tuple):
            for item in obj:
                _traverse(item)

    _traverse(flow_params)
    return flow_params

def replace_dots(value, arg):
    """
    Replaces all occurrences of '.' with the provided replacement string 'arg' in the given string 'value'.
    """
    # Validate input types
    if value is None:
        raise ValueError("value cannot be None")
    if arg is None:
        raise ValueError("arg cannot be None")
    try:
        original = str(value)
    except Exception as exc:
        raise TypeError("value must be convertible to a string") from exc
    try:
        replacement = str(arg)
    except Exception as exc:
        raise TypeError("arg must be convertible to a string") from exc

    # Perform the replacement
    return original.replace('.', replacement)

def subclasses(cls):
    """Return all subclasses of a class, recursively"""
    if not isinstance(cls, type):
        raise TypeError('subclasses requires a class')
    seen = set()
    queue = {cls}
    while queue:
        current = queue.pop()
        seen.add(current)
        for sub in current.__subclasses__():
            if sub not in seen:
                queue.add(sub)
    seen.discard(cls)
    return seen

def string_to_int(string: str, alphabet: List[str]) -> int:
    """
    Convert a string to a number, using the given alphabet.

    The input is assumed to have the most significant digit first.
    """
    if not alphabet:
        raise ValueError("alphabet must contain at least one character")
    base = len(alphabet)
    mapping = {char: idx for idx, char in enumerate(alphabet)}
    value = 0
    for char in string:
        if char not in mapping:
            raise ValueError(f"Character '{char}' not found in alphabet")
        value = value * base + mapping[char]
    return value

def get_repo_archive(url: str, destination_path: Path) -> Path:
    """Given an url and a destination path, retrieve and extract .tar.gz archive
    which contains 'desc' file for each package.
    Each .tar.gz archive corresponds to an Arch Linux repo ('core', 'extra', 'community').

    Args:
        url: url of the .tar.gz archive to download
        destination_path: the path on disk where to extract archive

    Returns:
        a directory Path where the archive has been extracted to.
    """
    import os
    import tarfile
    import tempfile
    import requests
    from pathlib import Path

    dest = Path(destination_path)

    # Ensure destination directory exists and is empty
    if dest.exists():
        if not dest.is_dir():
            raise OSError(f"Destination path {dest} exists and is not a directory.")
        # Check if empty
        try:
            if any(dest.iterdir()):
                raise OSError(f"Destination directory {dest} is not empty.")
        except PermissionError as exc:
            raise OSError(f"Cannot access destination directory {dest}: {exc}") from exc
    else:
        try:
            dest.mkdir(parents=True, exist_ok=True)
        except OSError as exc:
            raise OSError(f"Failed to create destination directory {dest}: {exc}") from exc

    # Download the archive to a temporary file
    try:
        tmp_fd, tmp_path = tempfile.mkstemp(suffix=".tar.gz")
        os.close(tmp_fd)  # we'll open it later with requests
        with open(tmp_path, 'wb') as out_file:
            with requests.get(url, stream=True, timeout=60) as resp:
                resp.raise_for_status()
                for chunk in resp.iter_content(chunk_size=8192):
                    if chunk:
                        out_file.write(chunk)
    except requests.RequestException as exc:
        # Clean up temp file if it was created
        if os.path.exists(tmp_path):
            os.remove(tmp_path)
        raise RuntimeError(f"Failed to download archive from {url}: {exc}") from exc
    except Exception as exc:
        if os.path.exists(tmp_path):
            os.remove(tmp_path)
        raise RuntimeError(f"Unexpected error during download: {exc}") from exc

    # Extract the archive
    try:
        with tarfile.open(tmp_path, mode='r:gz') as tar:
            tar.extractall(path=dest)
    except tarfile.TarError as exc:
        raise RuntimeError(f"Failed to extract archive {tmp_path}: {exc}") from exc
    finally:
        # Remove the temporary file
        try:
            os.remove(tmp_path)
        except OSError:
            pass

    return dest

def os_is_mac():
    """Checks if the os is macOS

    :return: True if macOS, False otherwise
    :rtype: bool
    """
    try:
        return os.uname().sysname == 'Darwin'
    except AttributeError:
        return False

def regex_dict(item):
    """
    Convert *.cpp keys to regex keys

    Given a dict where the keys are all filenames with wildcards, convert only
    the keys into equivalent regexes and leave the values intact.

    Example:

    rules = {
        '*.cpp':
            {'a': 'arf', 'b': 'bark', 'c': 'coo'},
        '*.h':
            {'h': 'help'}
    }
    regex_keys = regex_dict(rules)

    Args:
        item: dict to convert
    Returns:
        dict with keys converted to regexes
    """
    if not isinstance(item, dict):
        raise TypeError("Expected a dictionary as input")
    new_dict = {}
    for key, value in item.items():
        if isinstance(key, str):
            try:
                pattern = '^' + re.escape(key).replace(r'\*', '.*') + '$'
                new_key = re.compile(pattern)
            except re.error:
                new_key = key
        else:
            new_key = key
        new_dict[new_key] = value
    return new_dict

def unquote(name):
    """Remove quote from the given name."""
    if not isinstance(name, str):
        raise TypeError("name must be a string")
    # Remove surrounding single or double quotes if both ends match
    if len(name) > 1:
        if (name[0] == '"' and name[-1] == '"') or (name[0] == "'" and name[-1] == "'"):
            return name[1:-1]
    return name

def split(s, platform='this'):
    """Multi-platform variant of shlex.split() for command‑line splitting.
    For use with subprocess, for argv injection etc. Using fast REGEX.

    platform: 'this' = auto from current platform;
              1 = POSIX;
              0 = Windows/CMD
              (other values reserved)
    """
    import shlex
    if not isinstance(s, (str, bytes)):
        raise TypeError("Input must be a string or bytes")
    if isinstance(s, bytes):
        try:
            s = s.decode()
        except Exception as exc:
            raise ValueError("Byte input could not be decoded to text") from exc

    if platform == 'this':
        import sys
        platform = 0 if sys.platform.startswith('win') else 1

    if platform in (1, 'posix'):
        try:
            return shlex.split(s, posix=True)
        except TypeError:
            # posix argument not supported (Python 2)
            return shlex.split(s)
    elif platform in (0, 'windows', 'cmd'):
        try:
            return shlex.split(s, posix=False)
        except TypeError:
            return shlex.split(s)
    else:
        raise ValueError(f"Invalid platform value: {platform}")

def parse_frequency(frequency):
    '''
    Given a frequency string with a number and a unit of time, return a corresponding
    datetime.timedelta instance or None if the frequency is None or "always".

    For instance, given "3 weeks", return datetime.timedelta(weeks=3)

    Raise ValueError if the given frequency cannot be parsed.
    '''
    if frequency is None or (isinstance(frequency, str) and frequency.strip().lower() == "always"):
        return None

    if not isinstance(frequency, str):
        raise ValueError("Frequency must be a string or None")

    import re
    pattern = r'^\s*(\d+(?:\.\d+)?)\s*([a-zA-Z]+)\s*$'
    match = re.match(pattern, frequency)
    if not match:
        raise ValueError(f"Cannot parse frequency: {frequency!r}")

    amount_str, unit = match.groups()
    try:
        amount = float(amount_str)
    except ValueError:
        raise ValueError(f"Invalid numeric part in frequency: {amount_str!r}")

    unit = unit.lower()
    # Normalize unit names
    unit_map = {
        'day': 'days', 'days': 'days',
        'week': 'weeks', 'weeks': 'weeks',
        'hour': 'hours', 'hours': 'hours',
        'minute': 'minutes', 'minutes': 'minutes',
        'second': 'seconds', 'seconds': 'seconds',
        'month': 'days', 'months': 'days',
        'year': 'days', 'years': 'days',
    }

    if unit not in unit_map:
        raise ValueError(f"Unrecognized time unit in frequency: {unit!r}")

    if unit in ('month', 'months'):
        # approximate month as 30 days
        return datetime.timedelta(days=amount * 30)
    if unit in ('year', 'years'):
        # approximate year as 365 days
        return datetime.timedelta(days=amount * 365)

    kwargs = {unit_map[unit]: amount}
    return datetime.timedelta(**kwargs)

def is_local(host):
    """
    Checks if the host is the localhost

    :param host: The hostname or ip
    :return: True if the host is the localhost
    """
    if not host:
        return False

    # Quick string checks for common representations
    if host.lower() in {"localhost", "127.0.0.1", "::1"}:
        return True

    try:
        # Resolve the host to all possible addresses
        info = socket.getaddrinfo(host, None)
    except socket.gaierror:
        # Could not resolve; cannot be local
        return False

    # Loop over resolved addresses and check if any is in the loopback range
    try:
        import ipaddress
    except ImportError:
        # Fallback for environments without ipaddress module
        def is_loopback(ip):
            # Basic checks for IPv4 127.0.0.0/8 and IPv6 ::1
            if ip.startswith("127.") or ip == "::1":
                return True
            return False
    else:
        def is_loopback(ip):
            try:
                return ipaddress.ip_address(ip).is_loopback
            except ValueError:
                return False

    for entry in info:
        # entry[4] is the sockaddr; for IPv4 it is (ip, port), for IPv6 (ip, port, flow, scope)
        sockaddr = entry[4]
        addr = sockaddr[0]
        if is_loopback(addr):
            return True

    return False

def run_command(commands, args, cwd=None, verbose=False, hide_stderr=False, env=None):
    """Call the given command(s)."""
    # Normalize inputs
    if isinstance(commands, (str, bytes)):
        cmd_candidates = [commands]
    elif isinstance(commands, (list, tuple)):
        cmd_candidates = list(commands)
    else:
        raise ValueError("commands must be a string, bytes, list or tuple")

    if isinstance(args, (str, bytes)):
        args_list = [args]
    elif isinstance(args, (list, tuple)):
        args_list = list(args)
    else:
        raise ValueError("args must be a string, bytes, list or tuple")

    if not cmd_candidates:
        raise ValueError("no commands provided")

    # Determine stderr handling
    stderr = subprocess.DEVNULL if hide_stderr else subprocess.PIPE

    last_exception = None
    for idx, cmd in enumerate(cmd_candidates):
        cmd_combined = [cmd] + args_list
        if verbose:
            print("Executing:", " ".join(map(str, cmd_combined)))

        try:
            result = subprocess.run(
                cmd_combined,
                cwd=cwd,
                env=env,
                stdout=subprocess.PIPE,
                stderr=stderr,
                text=True,
                check=True,  # raise CalledProcessError on non-zero exit
            )
            # On success, return CompletedProcess
            return result
        except FileNotFoundError:
            # Command not found, try next candidate
            last_exception = FileNotFoundError(f"Command not found: {cmd}")
            continue
        except subprocess.CalledProcessError as exc:
            # If this is not the last candidate, try the next one
            if idx < len(cmd_candidates) - 1:
                last_exception = exc
                continue
            # Otherwise re-raise the exception
            raise

    # If we've exhausted all candidates, raise the last recorded exception
    if last_exception is not None:
        raise last_exception
    else:
        raise RuntimeError("No valid command could be executed")

def is_ipv4(target):
    """Test if IPv4 address or not"""
    if isinstance(target, ipaddress.IPv4Address):
        return True
    try:
        return ipaddress.ip_address(target).version == 4
    except ValueError:
        return False

def find_roots(
    graph: "Graph", prop: "URIRef", roots: Optional[Set["Node"]] = None
) -> Set["Node"]:
    """
    Find the roots in some sort of transitive hierarchy.

    find_roots(graph, rdflib.RDFS.subClassOf)
    will return a set of all roots of the sub-class hierarchy

    Assumes triple of the form (child, prop, parent), i.e. the direction of
    RDFS.subClassOf or SKOS.broader
    """
    try:
        # Collect all nodes that appear as subjects (children) or objects (parents)
        all_nodes: Set["Node"] = set()
        parent_nodes: Set["Node"] = set()

        for child, p, parent in graph.triples((None, prop, None)):
            if p != prop:
                continue
            all_nodes.add(child)
            all_nodes.add(parent)
            parent_nodes.add(parent)

        # If a specific set of candidates was supplied, limit to that subset
        if roots is not None:
            candidate_nodes = set(roots)
        else:
            candidate_nodes = all_nodes

        # Nodes that never appear as a parent are the roots
        root_candidates = candidate_nodes - parent_nodes
        return set(root_candidates)

    except Exception as exc:
        # The graph object might not support the triples method or prop might not be a URIRef
        raise ValueError(
            f"Unable to traverse the graph for property {prop!r}: {exc}"
        ) from exc

def make_array(shape, dtype=np.dtype("float32")):
    """
    Function to create an array with shape and dtype.

    Parameters
    ----------
    shape : tuple
        shape of the array to create
    dtype : `numpy.dtype`
        data-type of the array to create

    Returns
    -------
    numpy.ndarray
        An array with the specified shape and dtype.
    """
    # Validate and normalise the shape argument
    try:
        if shape is None:
            raise TypeError("Shape must be a tuple, list, or int, not None")
        if isinstance(shape, (int, np.integer)):
            shape_tuple = (int(shape),)
        else:
            shape_tuple = tuple(int(dim) for dim in shape)
    except Exception as exc:
        raise ValueError(f"Invalid shape argument: {shape!r}") from exc

    # Ensure dtype is a valid NumPy dtype
    try:
        dtype_obj = np.dtype(dtype)
    except Exception as exc:
        raise TypeError(f"Invalid dtype argument: {dtype!r}") from exc

    # Create and return the array; use empty for speed (uninitialised memory)
    try:
        return np.empty(shape_tuple, dtype=dtype_obj)
    except Exception as exc:
        raise RuntimeError(f"Failed to create array of shape {shape_tuple} and dtype {dtype_obj}") from exc

def load_configurations(config_filenames, overrides=None, resolve_env=True):
    '''
    Given a sequence of configuration filenames, load and validate each configuration file. Return
    the results as a tuple of: dict of configuration filename to corresponding parsed configuration,
    and sequence of logging.LogRecord instances containing any parse errors.
    '''
    import os
    import json
    import yaml
    import toml
    import configparser
    import logging

    # Ensure config_filenames is iterable
    if isinstance(config_filenames, str):
        config_filenames = [config_filenames]
    configs = {}
    error_records = []

    def _create_error_record(path, message, exc=None):
        record = logging.makeLogRecord({
            'name': 'config_loader',
            'level': logging.ERROR,
            'pathname': path,
            'lineno': 0,
            'msg': message,
            'args': (),
            'exc_info': exc
        })
        return record

    for cfg_path in config_filenames:
        try:
            with open(cfg_path, 'r', encoding='utf-8') as fp:
                content = fp.read()
        except FileNotFoundError as e:
            error_records.append(_create_error_record(cfg_path,
                                                       f'Configuration file not found: {cfg_path}'))
            continue
        except Exception as e:
            error_records.append(_create_error_record(cfg_path,
                                                       f'Error reading configuration file {cfg_path}: {e}',
                                                       exc_info=True))
            continue

        ext = os.path.splitext(cfg_path)[1].lower()
        try:
            if ext == '.json':
                data = json.loads(content)
            elif ext in ('.yaml', '.yml'):
                data = yaml.safe_load(content)
            elif ext == '.toml':
                data = toml.loads(content)
            elif ext == '.ini':
                parser = configparser.ConfigParser()
                parser.read_string(content)
                data = {s: dict(parser[s]) for s in parser.sections()}
            else:
                # Default to JSON
                data = json.loads(content)
        except Exception as e:
            error_records.append(_create_error_record(cfg_path,
                                                       f'Error parsing configuration file {cfg_path}: {e}',
                                                       exc_info=True))
            continue

        # Simple validation: configuration must be a dict
        if not isinstance(data, dict):
            error_records.append(_create_error_record(cfg_path,
                                                       f'Parsed configuration is not a dictionary: {type(data)}'))
            continue

        # Resolve environment variables if requested
        if resolve_env:
            def _resolve(value):
                if isinstance(value, str):
                    return os.path.expandvars(value)
                if isinstance(value, dict):
                    return {k: _resolve(v) for k, v in value.items()}
                if isinstance(value, list):
                    return [_resolve(v) for v in value]
                return value
            data = _resolve(data)

        # Apply overrides if any
        if overrides and isinstance(overrides, dict):
            data.update(overrides)

        configs[cfg_path] = data

    return configs, error_records

def force_string(obj):
    """
    This function returns the bytes object corresponding to ``obj``
    in case it is a string using UTF-8. 
    """
    if isinstance(obj, str):
        return obj.encode('utf-8')
    if isinstance(obj, numpy.ndarray) and obj.dtype.kind == 'U':
        return obj.astype('S')
    return obj

@classmethod
    def protocol_handlers(cls, protocol_version=None):
        """
        Return a dictionary of available Bolt protocol handlers,
        keyed by version tuple. If an explicit protocol version is
        provided, the dictionary will contain either zero or one items,
        depending on whether that version is supported. If no protocol
        version is provided, all available versions will be returned.

        :param protocol_version: tuple identifying a specific protocol
            version (e.g. (3, 5)) or None
        :return: dictionary of version tuple to handler class for all
            relevant and supported protocol versions
        :raise TypeError: if protocol version is not passed in a tuple
        """
        if protocol_version is not None:
            if not isinstance(protocol_version, tuple) or len(protocol_version) != 2:
                raise TypeError(
                    "protocol_version must be a tuple of two integers (major, minor)"
                )
            protocols = {}
            if hasattr(cls, "HANDLERS") and isinstance(cls.HANDLERS, dict):
                handler = cls.HANDLERS.get(protocol_version)
                if handler is not None:
                    protocols[protocol_version] = handler
            else:
                for subcls in cls.__subclasses__():
                    ver = getattr(subcls, "VERSION", None)
                    if ver == protocol_version:
                        protocols[protocol_version] = subcls
            return protocols

        # No specific version requested: return all supported handlers
        protocols = {}
        if hasattr(cls, "HANDLERS") and isinstance(cls.HANDLERS, dict):
            protocols.update(cls.HANDLERS)
        else:
            for subcls in cls.__subclasses__():
                ver = getattr(subcls, "VERSION", None)
                if isinstance(ver, tuple) and len(ver) == 2:
                    protocols[ver] = subcls
        return protocols

@classmethod
def from_raw_values(cls, values):
    """Create a Bookmarks object from a list of raw bookmark string values.

    You should not need to use this method unless you want to deserialize
    bookmarks.

    :param values: ASCII string values (raw bookmarks)
    :type values: Iterable[str]
    """
    if values is None:
        values = []
    # Validate that the input is iterable
    try:
        iterator = iter(values)
    except TypeError:
        raise TypeError("values must be an iterable of strings") from None

    bookmarks = []
    for raw in values:
        if not isinstance(raw, str):
            raise TypeError("All values in the iterable must be strings")
        # Attempt to parse each raw string into a Bookmark instance.
        try:
            # Many bookmark implementations expose a `from_raw` classmethod.
            bookmark = Bookmark.from_raw(raw)
        except AttributeError:
            # Fallback: try a constructor that accepts a raw string.
            try:
                bookmark = Bookmark(raw)
            except Exception as exc:
                raise ValueError(f"Cannot instantiate a Bookmark from raw value: {raw}") from exc
        except Exception as exc:
            raise ValueError(f"Cannot parse bookmark from raw value: {raw}") from exc
        bookmarks.append(bookmark)

    # Construct a Bookmarks instance.  Accept both positional and keyword
    # arguments to be tolerant of the underlying API.
    try:
        return cls(bookmarks)
    except TypeError:
        # Some implementations accept the keyword 'bookmarks'.
        return cls(bookmarks=bookmarks)

def _get_seq_with_type(seq, bufsize=None):
    """Return a (sequence, type) pair.
    Sequence is derived from *seq*
    (or is *seq*, if that is of a sequence type).
    """
    # If seq is a string or bytes, keep it as is
    if isinstance(seq, (str, bytes)):
        return (seq, type(seq))

    # If seq looks like a sequence (has __len__ and __getitem__)
    if hasattr(seq, "__len__") and hasattr(seq, "__getitem__"):
        return (seq, type(seq))

    # Try to consume seq into a list (handles iterators/generators)
    try:
        seq_list = list(seq)
    except TypeError:
        raise TypeError(f"Input {seq!r} is not iterable")

    return (seq_list, type(seq_list))

def scale(self, other=None):
    """Get or set the scale of the graph.

    If *other* is ``None``, return the scale of this graph.

    If a numeric *other* is provided, rescale to that value.
    If the graph has unknown or zero scale,
    rescaling that will raise :exc:`~.LenaValueError`.

    To get meaningful results, graph's fields are used.
    Only the last coordinate is rescaled.
    For example, if the graph has *x* and *y* coordinates,
    then *y* will be rescaled, and for a 3-dimensional graph
    *z* will be rescaled.
    All errors are rescaled together with their coordinate.
    """
    # Getter
    if other is None:
        # Prefer private attribute if exists
        if hasattr(self, "_scale"):
            return getattr(self, "_scale")
        if hasattr(self, "scale"):
            return getattr(self, "scale")
        # No scale set
        return None

    # Setter – validate *other*
    if not isinstance(other, (int, float, np.number)):
        raise TypeError("Scale must be a numeric value.")
    # Current scale
    cur = None
    if hasattr(self, "_scale"):
        cur = getattr(self, "_scale")
    elif hasattr(self, "scale"):
        cur = getattr(self, "scale")

    if cur is None or not isinstance(cur, (int, float, np.number)) or cur == 0:
        raise LenaValueError("Unable to rescale graph with unknown or zero scale.")

    factor = other / cur

    # Identify last coordinate (assume ordering z > y > x)
    axis_names = ["x", "y", "z"]
    last_coord = None
    for name in reversed(axis_names):
        if hasattr(self, name):
            val = getattr(self, name)
            if val is not None:
                if isinstance(val, (np.ndarray, list, tuple)):
                    last_coord = name
                    break
    if last_coord is None:
        raise AttributeError("No coordinate found to rescale.")

    # Rescale coordinate data
    try:
        coord = getattr(self, last_coord)
        if isinstance(coord, np.ndarray):
            np.multiply(coord, factor, out=coord)
        else:
            setattr(self, last_coord, [v * factor for v in coord])
    except Exception as exc:
        raise RuntimeError(f"Failed to rescale coordinate '{last_coord}': {exc}") from exc

    # Rescale associated error if present
    err_attr = f"{last_coord}_err"
    if hasattr(self, err_attr):
        err = getattr(self, err_attr)
        try:
            if isinstance(err, np.ndarray):
                np.multiply(err, factor, out=err)
            else:
                setattr(self, err_attr, [v * factor for v in err])
        except Exception as exc:
            raise RuntimeError(f"Failed to rescale error '{err_attr}': {exc}") from exc

    # Update stored scale
    if hasattr(self, "_scale"):
        setattr(self, "_scale", other)
    else:
        setattr(self, "scale", other)

    return None

def determineMetaclass(bases, explicit_mc=None):
    """Determine metaclass from 1+ bases and optional explicit __metaclass__"""

    # Ensure bases is a list-like iterable
    bases_list = list(bases)

    # If an explicit metaclass is provided, use it after validation
    if explicit_mc is not None:
        if not isinstance(explicit_mc, type):
            raise TypeError(
                f"__metaclass__ must be a class, got {type(explicit_mc).__name__}"
            )
        # Verify compatibility with each base's metaclass
        for b in bases_list:
            if not isinstance(b, type):
                raise TypeError(f"Base {b!r} is not a class")
            if not issubclass(type(b), explicit_mc):
                raise TypeError(
                    f"Metaclass conflict: {type(b).__name__} is not a subclass "
                    f"of {explicit_mc.__name__}"
                )
        return explicit_mc

    # No explicit metaclass: compute the most derived metaclass among bases
    if not bases_list:
        # No bases: default to the standard metaclass
        return type

    # Start with the metaclass of the first base
    try:
        meta = type(bases_list[0])
    except Exception as exc:
        raise TypeError(f"Cannot determine metaclass for base {bases_list[0]!r}") from exc

    for b in bases_list[1:]:
        if not isinstance(b, type):
            raise TypeError(f"Base {b!r} is not a class")
        bmeta = type(b)
        if issubclass(meta, bmeta):
            # Current meta dominates
            continue
        if issubclass(bmeta, meta):
            # New meta is more derived
            meta = bmeta
            continue
        # Metaclasses are incompatible
        raise TypeError(f"Metaclass conflict between {meta.__name__} and {bmeta.__name__}")

    return meta

def pop(self, key, default=__marker):
        """
        D.pop(k[,d]) -> v, remove specified key and return the corresponding value.
        If key is not found, d is returned if given, otherwise KeyError is raised.
        """
        if key not in self:
            if default is __marker:
                raise KeyError(key)
            return default
        return super().pop(key)

def popitem(self):
    """Remove and return the `(key, value)` pair least recently used."""
    return super().popitem(last=False)

def popitem(self):
    """Remove and return the `(key, value)` pair most recently used."""
    try:
        key, value = dict.popitem(self)
        return (key, value)
    except KeyError as e:
        raise KeyError('dictionary is empty') from e

def popitem(self):
    """Remove and return a random `(key, value)` pair."""
    if not self:
        raise KeyError('dict is empty')
    import random
    key = random.choice(list(self))
    return (key, self.pop(key))

def _create_converter(self) -> _converting._Converter:
    """Create the parameter style converter.

    Returns the parameter style converter (:class:`._converting._Converter`).
    """
    def _convert(value):
        # If the value is a mapping, convert to key=value pairs joined by '&'
        if isinstance(value, dict):
            parts = []
            for k, v in value.items():
                # Skip keys with None values
                if v is None:
                    continue
                parts.append(f"{k}={v}")
            return "&".join(parts)
        # If the value is iterable but not a string, join elements with commas
        if hasattr(value, "__iter__") and not isinstance(value, (str, bytes)):
            return ",".join(str(item) for item in value)
        # Fallback: just return string representation
        return str(value)
    return _converting._Converter(_convert)

