def identify_request(request: RequestType):
    """Try to identify whether this is a Diaspora request.

    Try first public message. Then private message. The check if this is a legacy payload.
    """
    if request is None:
        return False
    body = request.body

    # Try JSON payload
    try:
        if isinstance(body, bytes):
            body_str = body.decode("utf-8")
        elif isinstance(body, str):
            body_str = body
        else:
            body_str = str(body)
        data = json.loads(body_str)
        if "encrypted_magic_envelope" in data:
            return True
    except Exception:
        pass

    # Try XML payload
    try:
        if isinstance(body, bytes):
            xml_data = body
        else:
            xml_data = body.encode("utf-8")
        xml = etree.fromstring(xml_data)
        if xml.tag == MAGIC_ENV_TAG:
            return True
    except Exception:
        pass

    return False

def identify_request(request: RequestType) -> bool:
    """Try to identify whether this is a Matrix request."""
    try:
        # Grab the request path from a variety of common attributes
        path = None
        for attr in ("path", "uri", "url"):
            if hasattr(request, attr):
                path = getattr(request, attr)
                break

        # If a path is available, a Matrix request typically starts with "/_matrix"
        if isinstance(path, str) and path.startswith("/_matrix"):
            return True

        # Matrix requests often contain an access_token query parameter
        if hasattr(request, "GET") and hasattr(request.GET, "get"):
            if request.GET.get("access_token"):
                return True
        if hasattr(request, "query_params") and hasattr(request.query_params, "get"):
            if request.query_params.get("access_token"):
                return True

        # Check for common Matrix-specific headers
        headers = None
        if hasattr(request, "headers") and isinstance(request.headers, dict):
            headers = request.headers
        elif hasattr(request, "META") and isinstance(request.META, dict):
            headers = request.META

        if isinstance(headers, dict):
            for key in headers:
                if key.lower() == "x-matrix-client-token":
                    return True

        # If none of the checks matched, it's unlikely to be a Matrix request
        return False
    except Exception:
        # If the request object doesn't expose the expected attributes or an
        # unexpected error occurs, conservatively return False
        return False

def format_dt(dt):
    """Format a datetime in the way that D* nodes expect."""
    if not hasattr(dt, "strftime"):
        raise TypeError("format_dt expected a datetime-like object")
    # Convert to UTC if timezone-aware; ignore if naive
    if getattr(dt, "tzinfo", None):
        try:
            dt = dt.astimezone(datetime.timezone.utc)
        except Exception:
            pass
    return dt.strftime("%Y-%m-%dT%H:%M:%SZ")

def fetch_content_type(url: str) -> Optional[str]:
    """Fetch the HEAD of the remote url to determine the content type."""
    scheme, netloc, _, _, _ = urlparse.urlsplit(url)
    if scheme not in ("http", "https"):
        return None
    try:
        req = Request(url, method="HEAD")
        with urlopen(req) as resp:
            return resp.info().get("content-type", None)
    except Exception:
        return None

def xml_children_as_dict(node):
    """Turn the children of node <xml> into a dict, keyed by tag name.
    This is only a shallow conversation - child nodes are not recursively processed.
    """
    children_dict = {}
    try:
        for child in node:
            tag = child.tag
            if tag in children_dict:
                existing = children_dict[tag]
                if isinstance(existing, list):
                    existing.append(child)
                else:
                    children_dict[tag] = [existing, child]
            else:
                children_dict[tag] = child
    except Exception:
        # If node is not iterable or has no children, return empty dict
        pass
    return children_dict

def get_nodeinfo_well_known_document(url, document_path=None):
    """
    Generate a NodeInfo .well-known document.

    See spec: http://nodeinfo.diaspora.software

    :arg url: The full base url with protocol, ie https://example.com
    :arg document_path: Custom NodeInfo document path if supplied (optional)
    :returns: dict
    """
    try:
        if not url:
            raise ValueError("Base URL must be provided")
        base = url.rstrip('/')
        # Build hrefs for the two supported NodeInfo schema versions
        if document_path:
            # Normalize the custom path; it may include leading slashes
            path = document_path.lstrip('/')
            href_1_0 = f"{base}/{path}/1.0"
            href_2_0 = f"{base}/{path}/2.0"
        else:
            # Default path to the spec's recommended location
            href_1_0 = f"{base}/.well-known/nodeinfo/1.0"
            href_2_0 = f"{base}/.well-known/nodeinfo/2.0"

        return {
            "links": [
                {
                    "rel": "http://nodeinfo.diaspora.software/ns/schema/1.0",
                    "href": href_1_0
                },
                {
                    "rel": "http://nodeinfo.diaspora.software/ns/schema/2.0",
                    "href": href_2_0
                }
            ]
        }
    except Exception:
        # Gracefully handle unexpected errors; callers may choose to respond with a 5xx
        return None

def parse_diaspora_webfinger(document: str) -> Dict:
    """
    Parse Diaspora webfinger which is either in JSON format (new) or XRD (old).

    https://diaspora.github.io/diaspora_federation/discovery/webfinger.html
    """
    if not document:
        return None
    # Try JSON first
    try:
        data = json.loads(document)
        if isinstance(data, dict):
            result: Dict = {}
            if "subject" in data:
                result["subject"] = data["subject"]
            links = {}
            for link in data.get("links", []):
                rel = link.get("rel")
                href = link.get("href")
                if rel and href:
                    links[rel] = href
            result["links"] = links
            # Convenience aliases
            result["hcard_url"] = links.get("hcard")
            result["lrdd_url"] = links.get("lrdd")
            return result
    except Exception:
        # Not JSON; fall back to XRD
        pass

    # Try XRD (XML) parsing
    try:
        def _strip_ns(tag):
            return tag.split("}")[-1] if "}" in tag else tag

        root = ET.fromstring(document)
        result: Dict = {}
        # Find subject
        subject_el = None
        for el in root.iter():
            if _strip_ns(el.tag).lower() == "subject":
                subject_el = el
                break
        if subject_el is not None:
            result["subject"] = subject_el.text
        # Find links
        links = {}
        for el in root.iter():
            if _strip_ns(el.tag).lower() == "link":
                rel = el.attrib.get("rel")
                href = el.attrib.get("href")
                if rel and href:
                    links[rel] = href
        result["links"] = links
        result["hcard_url"] = links.get("hcard")
        result["lrdd_url"] = links.get("lrdd")
        return result
    except Exception:
        # Unable to parse
        return None

def try_retrieve_webfinger_document(handle: str) -> Optional[str]:
    """Try to retrieve an RFC7033 webfinger document. Does not raise if it fails."""
    try:
        # Form the resource identifier, ensuring it starts with "acct:"
        resource = handle if handle.startswith("acct:") else f"acct:{handle}"
        # Extract the host part after the '@' in the resource
        try:
            host = resource.split("@", 1)[1]
        except IndexError:
            # Cannot find host part; invalid handle
            return None
        # Construct the well‑known webfinger URL
        url = f"https://{host}/.well-known/webfinger?resource={urllib.parse.quote(resource, safe='')}"
        # Attempt to fetch the document
        with urllib.request.urlopen(url) as response:
            if response.status != 200:
                return None
            return response.read().decode("utf-8")
    except Exception:
        # Suppress all exceptions: return None on failure
        return None

def retrieve_and_parse_diaspora_webfinger(handle):
    """
    Retrieve a and parse a remote Diaspora webfinger document.

    :arg handle: Remote handle to retrieve
    :returns: dict
    """
    try:
        host = handle.split("@")[1]
    except AttributeError:
        logger.warning("retrieve_and_parse_diaspora_webfinger: invalid handle given: %s", handle)
        return None
    document, code, exception = fetch_document(
        host=host, path="/.well-known/webfinger?resource=acct:%s" % quote(handle),
    )
    if document:
        return parse_diaspora_webfinger(document)
    hostmeta = retrieve_diaspora_host_meta(host)
    if not hostmeta:
        return None
    url = hostmeta.find_link(rels="lrdd").template.replace("{uri}", quote(handle))
    document, code, exception = fetch_document(url)
    if exception:
        return None
    return parse_diaspora_webfinger(document)

def list_of_file_names(settings_dirs, spec_option):
    """Create a new IniType complex type
    """
    import os
    import fnmatch
    from pathlib import Path

    if spec_option is None:
        spec_option = '*'
    # Normalize the settings_dirs to a list
    if isinstance(settings_dirs, (str, Path)):
        dirs = [settings_dirs]
    else:
        try:
            dirs = list(settings_dirs)
        except TypeError:
            dirs = [settings_dirs]
    file_list = []

    for d in dirs:
        try:
            for root, _, names in os.walk(str(d)):
                for name in names:
                    if fnmatch.fnmatch(name, spec_option):
                        file_list.append(os.path.join(root, name))
        except (OSError, TypeError):
            # Ignore directories that cannot be accessed
            continue

    return sorted(file_list)

@classmethod
    def ansible_config_manager(cls):
        """Gets the ansible config manager. """
        try:
            from ansible.constants import ANSIBLE_CONFIG
            return ANSIBLE_CONFIG
        except Exception:
            import os
            path = os.getenv("ANSIBLE_CONFIG")
            if path and os.path.isfile(path):
                return path
            default_path = os.path.join(os.getcwd(), "ansible.cfg")
            if os.path.isfile(default_path):
                return default_path
            raise RuntimeError("Ansible configuration file could not be located.")

def workspace_manager(cls):
    """
    Gets the workspace manager.
    """
    def find_manager(con):
        # Check for the workspace manager by type attribute
        if getattr(con, 'type', None) == 'workspace_manager':
            return con
        # Recurse through child nodes if present
        for child in getattr(con, 'nodes', []):
            mgr = find_manager(child)
            if mgr:
                return mgr
        return None

    # Get the root Con (may raise if root() not defined)
    try:
        root = cls.root()
    except Exception as e:
        raise RuntimeError("Failed to obtain root Con: %s" % e)

    manager = find_manager(root)
    if manager is None:
        raise RuntimeError("Workspace manager not found in the hierarchy")

    return manager

@classmethod
    def plugins_manager(cls):
        """Gets the plugin manager."""
        try:
            if not hasattr(cls, "_plugins_manager"):
                cls._plugins_manager = {}
            return cls._plugins_manager
        except Exception as exc:
            raise RuntimeError("Unable to retrieve plugin manager: %s" % exc) from exc

@classmethod
    def validate_from_content(cls, spec_content=None):
        """validates that spec (YAML) content has all required fields

        :param spec_content: content of spec file
        :raise IRValidatorException: when mandatory data
        is missing in spec file
        :return: Dictionary with data loaded from a spec (YAML) file
        """
        if spec_content is None:
            raise IRValidatorException("spec_content cannot be None")
        try:
            if isinstance(spec_content, str):
                # Treat the string as YAML content
                data = yaml.safe_load(spec_content)
        except Exception as e:
            raise IRValidatorException(f"Failed to parse spec content: {e}")
        if data is None:
            raise IRValidatorException("Could not load data from spec_content")
        if not isinstance(data, dict) or not data:
            raise IRValidatorException("Mandatory data missing or invalid in spec file")
        return data

@classmethod
    def validate_from_file(cls, yaml_file=None):
        """
        Loads & validates that a YAML file has all required fields

        :param yaml_file: Path to YAML file
        :raise IRValidatorException: when mandatory data is missing in file
        :return: Dictionary with data loaded from a YAML file
        """
        if yaml_file is None:
            raise IRValidatorException("yaml_file argument must be supplied")

        try:
            with open(yaml_file, "r") as f:
                data = yaml.safe_load(f)
        except FileNotFoundError as e:
            raise IRValidatorException(f"File not found: {yaml_file}") from e
        except Exception as e:
            raise IRValidatorException(f"Error reading YAML file: {e}") from e

        if data is None:
            raise IRValidatorException("YAML file is empty or contains no data")

        required_keys = getattr(cls, "REQUIRED_KEYS", None)
        if required_keys:
            missing = [key for key in required_keys if key not in data]
            if missing:
                raise IRValidatorException(
                    f"Missing required keys: {', '.join(missing)}"
                )

        return data

def _include_groups(self, parser_dict):
    """Resolves the include dict directive in the spec files. """
    if not isinstance(parser_dict, dict):
        raise TypeError("parser_dict must be a dictionary of groups")
    # Helper to recursively resolve includes while detecting cycles
    def _resolve_section(name, stack):
        if name in stack:
            raise ValueError(f"Circular include detected: {' -> '.join(stack + [name])}")
        section = parser_dict.get(name)
        if section is None:
            raise KeyError(f"Group '{name}' not found in parser_dict")
        if not isinstance(section, dict):
            return
        if 'include' in section or 'includes' in section:
            includes = section.pop('include', None) or section.pop('includes', None)
            if includes is None:
                return
            if not isinstance(includes, (list, tuple)):
                includes = [includes]
            for inc_name in includes:
                _resolve_section(inc_name, stack + [name])
                inc_section = parser_dict.get(inc_name)
                if inc_section is None:
                    raise KeyError(f"Included group '{inc_name}' not found for group '{name}'")
                if not isinstance(inc_section, dict):
                    continue
                for k, v in inc_section.items():
                    if k not in section:
                        section[k] = v
    # Resolve all top-level groups
    for group_name in list(parser_dict.keys()):
        _resolve_section(group_name, [])

def get_spec_defaults(self):
    """Resolve arguments' values from spec and other sources. """
    defaults = {}

    # fetch defaults from the _default_spec if it exists
    default_source = getattr(self, "_default_spec", None)
    if default_source is not None:
        if isinstance(default_source, dict):
            defaults.update(default_source)
        elif hasattr(default_source, "to_dict"):
            try:
                defaults.update(default_source.to_dict())
            except Exception:
                pass

    # apply overrides from the spec attribute
    spec_source = getattr(self, "spec", None)
    if spec_source is not None:
        if isinstance(spec_source, dict):
            defaults.update(spec_source)
        elif hasattr(spec_source, "to_dict"):
            try:
                defaults.update(spec_source.to_dict())
            except Exception:
                pass

    # finally, fill in any remaining defaults from the scheme's arguments
    if hasattr(self, "args"):
        for arg in getattr(self, "args"):
            try:
                if hasattr(arg, "name") and hasattr(arg, "default") and arg.name not in defaults:
                    if not isinstance(arg.default, NoDefault):
                        defaults[arg.name] = arg.default
            except Exception:
                continue

    return defaults

def get_deprecated_args(self):
    """Returning dict with options which deprecate others."""
    # Attempt to retrieve a mapping from the instance. If it is not
    # defined, fall back to an empty dictionary.
    mapping = getattr(self, "_deprecated_args", {})
    if not isinstance(mapping, dict):
        raise TypeError("Deprecated arguments mapping must be a dictionary.")
    # Ensure that all keys and values are strings
    for old_name, new_name in mapping.items():
        if not isinstance(old_name, str) or not isinstance(new_name, str):
            raise ValueError(
                f"Deprecated argument names and replacements must be strings: "
                f"{old_name!r} -> {new_name!r}"
            )
    return mapping

def validate_arg_deprecation(self, cli_args, answer_file_args):
    """Validates and prints the deprecated arguments.

    :param cli_args: the dict of arguments from cli
    :param answer_file_args:  the dict of arguments from files
    """
    import warnings

    # Ensure args are dictionaries
    if not isinstance(cli_args, dict):
        raise TypeError(f'cli_args must be a dict, got {type(cli_args)!r}')
    if not isinstance(answer_file_args, dict):
        raise TypeError(f'answer_file_args must be a dict, got {type(answer_file_args)!r}')

    # Retrieve deprecation mapping if defined; otherwise no deprecation handling
    deprecation_mapping = getattr(self, 'deprecated_arg_mapping', {})
    if not isinstance(deprecation_mapping, dict):
        raise TypeError('deprecated_arg_mapping must be a dict if defined')

    # Handle deprecated keys in cli_args
    for old_name, new_name in list(deprecation_mapping.items()):
        if old_name in cli_args:
            warnings.warn(
                f"Keyword argument '{old_name}' has been deprecated in favour of '{new_name}'. "
                f"'{old_name}' will be removed in a future version.",
                DeprecationWarning,
                stacklevel=3,
            )
            # Transfer the value to the new key if the new key hasn't been set
            if new_name not in cli_args:
                cli_args[new_name] = cli_args.pop(old_name)
            else:
                # If both old and new provided, prefer the new one and discard old
                cli_args.pop(old_name)

        if old_name in answer_file_args:
            warnings.warn(
                f"Answer file argument '{old_name}' is deprecated in favour of '{new_name}'. "
                f"Use the new name in subsequent executions.",
                DeprecationWarning,
                stacklevel=3,
            )
            if new_name not in answer_file_args:
                answer_file_args[new_name] = answer_file_args.pop(old_name)
            else:
                answer_file_args.pop(old_name)

    # Warn if the same argument is supplied in both sources
    for arg_name in set(cli_args) & set(answer_file_args):
        warnings.warn(
            f"Argument '{arg_name}' was supplied both on the command line and in the answer file; "
            "the command-line value will take precedence.",
            RuntimeWarning,
            stacklevel=3,
        )
    # No return value is required; the method performs validation and warnings only.

def get_parser_option_specs(self, command_name):
    """Gets all the options for the specified command

    :param command_name: the command name (main, virsh, ospd, etc...)
    :return: the list of all command options
    """
    # Prefer a dedicated attribute holding the options
    try:
        if hasattr(self, f"{command_name}_options"):
            return getattr(self, f"{command_name}_options")

        # Look for a dictionary that maps command names to option lists
        if hasattr(self, "command_options") and isinstance(self.command_options, dict):
            return self.command_options.get(command_name, [])

        # Try a method that returns the options
        method_name = f"get_{command_name}_options"
        if hasattr(self, method_name):
            method = getattr(self, method_name)
            if callable(method):
                return method()

        # If there is a parser registry, pull options from the parser
        if hasattr(self, "parsers") and isinstance(self.parsers, dict):
            parser = self.parsers.get(command_name)
            if parser:
                # argparse parsers expose _actions, optparse has option_list
                if hasattr(parser, "_actions"):
                    return parser._actions
                if hasattr(parser, "option_list"):
                    return parser.option_list
    except Exception:
        # Any unexpected error should result in an empty list rather than
        # breaking the caller.
        return []

    # Fallback empty list if nothing found
    return []

def get_option_spec(self, command_name, argument_name):
    """Gets the specification for the specified option name. """
    # Retrieve the command object from the stored commands.
    try:
        command = self.commands[command_name]
    except (AttributeError, KeyError):
        # If the command does not exist, issue a gentle warning and return None.
        if hasattr(self, "log"):
            self.log.warning("Command %r not found", command_name)
        else:
            try:
                import logging
                logging.getLogger(__name__).warning("Command %r not found", command_name)
            except Exception:
                pass
        return None

    # Attempt to fetch the option specification from the command.
    try:
        # Most CLI frameworks expose a mapping of arguments/options.
        options_attr = getattr(command, "options", None)
        if options_attr is None:
            options_attr = getattr(command, "args", None)
        return options_attr[argument_name]
    except (AttributeError, KeyError):
        # The specified option is missing; warn and return None.
        if hasattr(self, "log"):
            self.log.warning("Option %r not found in command %r", argument_name, command_name)
        else:
            try:
                import logging
                logging.getLogger(__name__).warning("Option %r not found in command %r",
                                                    argument_name, command_name)
            except Exception:
                pass
        return None

def get_silent_args(self, args):
    """
    list of silenced argument

    :param args: The received arguments.
    :return: list, slienced argument names
    """
    # If args is a list or tuple of strings, return those that look like options
    if isinstance(args, (list, tuple)):
        return [arg for arg in args
                if isinstance(arg, str) and arg.startswith('-') and arg != '-']
    # If args is a dict, return keys that look like options
    if isinstance(args, dict):
        return [k for k in args.keys()
                if isinstance(k, str) and k.startswith('-') and k != '-']
    # If args is a Namespace or has a __dict__, inspect its attributes
    if hasattr(args, '__dict__'):
        attr_dict = vars(args)
        return [k for k, v in attr_dict.items()
                if isinstance(k, str) and k.startswith('-') and k != '-']
    # Fallback: if args is iterable of key-value pairs
    try:
        return [k for k, v in args
                if isinstance(k, str) and k.startswith('-') and k != '-']
    except Exception:
        # Unable to interpret args; return empty list
        return []

def validate_requires_args(self, args):
    """Check if all the required arguments have been provided."""
    # Determine the iterable of required argument names. If the object
    # does not provide a `required` attribute we consider nothing required.
    required = getattr(self, "required", None)
    if not required:
        return

    missing = []

    # If `args` is a mapping, look up keys directly.  If it is not
    # a mapping (e.g., a list or tuple), try to resolve arguments
    # by index using an optional `arg_names` attribute that
    # maps positions to names.
    if isinstance(args, dict):
        for name in required:
            if name not in args or args[name] is None:
                missing.append(name)
    else:
        # Optionally support positional args with a known order
        names = getattr(self, "arg_names", [])
        for name in required:
            try:
                index = names.index(name)
                if args[index] is None:
                    missing.append(name)
            except (ValueError, IndexError):
                missing.append(name)

    if missing:
        raise ValueError(f"Missing required argument(s): {', '.join(missing)}")

def _get_conditionally_required_args(self, command_name, options_spec, args):
    """List arguments with ``required_when`` condition matched.

    :param command_name: the command name.
    :param options_spec:  the list of command spec options.
    :param args: the received input arguments
    :return: list, list of argument names with matched ``required_when``
        condition
    """
    matched = []
    if not options_spec:
        return matched

    # Normalize command_name & args for matching
    try:
        cmd = str(command_name)
    except Exception:
        cmd = None

    # Ensure args is a mapping if possible; otherwise keep as is
    try:
        args_mapping = dict(args)
    except Exception:
        args_mapping = None

    for opt in options_spec or []:
        # option may be a dict or object with attributes
        # Attempt to fetch name and required_when
        name = None
        req_when = None
        if isinstance(opt, dict):
            name = opt.get("name")
            req_when = opt.get("required_when")
        else:
            # Fallback to attribute access
            name = getattr(opt, "name", None)
            req_when = getattr(opt, "required_when", None)

        # Skip if no name or no condition
        if not name or req_when is None:
            continue

        # Determine if condition matches
        try:
            if callable(req_when):
                # Call with command_name and args (or mapping if provided)
                if args_mapping is not None:
                    result = req_when(cmd, args_mapping)
                else:
                    result = req_when(cmd, args)
            elif isinstance(req_when, (list, tuple, set)):
                # Condition is a list of command names
                result = cmd in req_when
            elif isinstance(req_when, dict):
                # Condition is a dict of required options; all must be present in args
                # e.g., {'opt_a': True, 'opt_b': False}
                # A key with truthy value means required only when that option
                # is present and truthy in args
                result = True
                for k, v in req_when.items():
                    if args_mapping is None:
                        result = False
                        break
                    val = args_mapping.get(k)
                    if bool(val) != bool(v):
                        result = False
                        break
            else:
                # Direct truthy value
                result = bool(req_when)
        except Exception:
            result = False

        if result:
            matched.append(name)

    return matched

def validate_length_args(self, args):
    """Check if value of arguments is not longer than length specified.

    :param args: The received arguments, either a mapping of argument names
        to values or a list of mappings one per argument.
    :raises ValueError: If an argument value exceeds its specified maximum
        length or if the input format is invalid.
    """
    # Resolve the runtime argument mapping
    if isinstance(args, dict):
        arg_items = list(args.items())
    elif isinstance(args, list):
        arg_items = []
        for i, item in enumerate(args):
            if isinstance(item, dict):
                if len(item) != 1:
                    raise ValueError(
                        f"Argument dict at index {i} contains {len(item)} keys; "
                        "expected exactly one"
                    )
                key, value = next(iter(item.items()))
                arg_items.append((key, value))
            else:
                raise TypeError(
                    f"Unsupported argument format at index {i}: "
                    f"{type(item).__name__}"
                )
    else:
        raise TypeError(
            f"Expected args to be a dict or a list of dicts; got {type(args).__name__}"
        )

    # Retrieve the specified limits from the parsed configuration
    spec = self.parsed_yaml.get("args", {})
    if not isinstance(spec, dict):
        raise TypeError(
            f"The 'args' specification should be a dict; got {type(spec).__name__}"
        )

    for arg_name, value in arg_items:
        arg_spec = spec.get(arg_name)
        if not isinstance(arg_spec, dict):
            continue  # No specific spec to validate against

        max_len = arg_spec.get("length")
        if max_len is None:
            continue  # No length constraint defined

        # Value must support len()
        try:
            actual_len = len(value)
        except Exception:
            # If len() is not supported, skip length validation for this value
            continue

        if not isinstance(max_len, int):
            raise TypeError(
                f"Length constraint for argument '{arg_name}' must be an int; "
                f"got {type(max_len).__name__}"
            )
        if actual_len > max_len:
            raise ValueError(
                f"Argument '{arg_name}' length {actual_len} exceeds "
                f"maximum allowed {max_len}"
            )

def validate_choices_args(self, args):
    """
    Check if value of choice arguments is one of the available choices.

    :param args: The received arguments (mapping of argument names to values).
    :raises ValueError: If an argument value is not a permitted choice.
    """
    # Retrieve the mapping of argument names to available choices.
    # The containing class is expected to expose the mapping in an attribute
    # named either ``choices`` or ``arg_choices`` (common patterns).
    choices_map = getattr(self, "choices", None) or getattr(self, "arg_choices", None)

    # If no choices map is defined, nothing to validate.
    if not choices_map:
        return

    # Accept either a dict or a list of (name, value) tuples.
    if isinstance(args, dict):
        items = args.items()
    elif isinstance(args, list):
        items = args
    else:
        raise TypeError(
            f"Invalid type for args: expected dict or list, got {type(args).__name__}"
        )

    for item in items:
        # For list case, each item should be a (name, value) tuple.
        if isinstance(item, tuple):
            if len(item) != 2:
                raise ValueError(
                    f"Choice argument item {item!r} should be a two‑element tuple"
                )
            arg_name, value = item
        else:
            # In dict case, item is already a (name, value) pair.
            arg_name, value = item

        # Only validate arguments that have a defined choice list.
        if arg_name in choices_map:
            allowed = choices_map[arg_name]
            if value not in allowed:
                raise ValueError(
                    f"Invalid choice for argument '{arg_name}': {value!r}. "
                    f"Expected one of {allowed!r}."
                )
            # If it passes, continue silently.
    # All arguments validated successfully. Return None.

def validate_min_max_args(self, args):
    """Check if value of arguments is between minimum and maximum values.

    :param args: The received arguments.
    """
    # Ensure args behaves like a mapping (e.g., dict)
    if not hasattr(args, "items"):
        raise TypeError("args must be a mapping of argument names to values")

    # Retrieve per-argument or global min/max limits from the instance, if they exist
    bounds_min = getattr(self, "min", {})
    bounds_max = getattr(self, "max", {})

    for name, value in args.items():
        # Determine the lower bound for this argument
        if isinstance(bounds_min, dict):
            min_val = bounds_min.get(name)
        else:
            min_val = bounds_min

        # Determine the upper bound for this argument
        if isinstance(bounds_max, dict):
            max_val = bounds_max.get(name)
        else:
            max_val = bounds_max

        # Validate against minimum
        if min_val is not None:
            try:
                if value < min_val:
                    raise ValueError(
                        f"Argument {name!r}={value} is less than minimum {min_val}"
                    )
            except TypeError as exc:
                raise TypeError(
                    f"Cannot compare value of argument {name!r} with minimum {min_val}"
                ) from exc

        # Validate against maximum
        if max_val is not None:
            try:
                if value > max_val:
                    raise ValueError(
                        f"Argument {name!r}={value} is greater than maximum {max_val}"
                    )
            except TypeError as exc:
                raise TypeError(
                    f"Cannot compare value of argument {name!r} with maximum {max_val}"
                ) from exc

    return args

def get_nested_custom_and_control_args(self, args):
    """Split input arguments to control nested and custom.

    Controls arguments: control the IR behavior. These arguments
        will not be put into the spec yml file
    Nested arguments: are used by the Ansible playbooks and will be put
        into the spec yml file.
    Custom arguments: Custom ansible variables to be used instead of the
        normal nested usage.

    :param args: the collected list of args.
    :return: (dict, dict): flat dicts (control_args, nested_args)
    """
    # Accept a dict or a list/iterable of (key, value) pairs
    if args is None:
        return {}, {}
    if isinstance(args, list) or isinstance(args, tuple):
        args = dict(args)
    if not isinstance(args, dict):
        raise TypeError(f"Expected dict or list of pairs, got {type(args).__name__}")
    control_args = {}
    nested_args = {}
    # Try to infer control keys from instance attributes if available
    control_keys = getattr(self, "control_keys", None)
    nested_keys = getattr(self, "nested_keys", None)
    # If no explicit lists, use heuristic: keys prefixed with '_' are control
    if control_keys is None:
        control_keys = {k for k in args if isinstance(k, str) and k.startswith("_")}
    if nested_keys is None:
        nested_keys = set(args) - control_keys
    for key, value in args.items():
        if key in control_keys:
            control_args[key] = value
        else:
            # All other keys are considered nested; custom args will be
            # included here as they are simply treated as normal nested
            # arguments that can override defaults.
            nested_args[key] = value
    return control_args, nested_args

def merge_extra_vars(vars_dict, extra_vars=None):
    """Extend ``vars_dict`` with ``extra-vars``

    :param vars_dict: Dictionary to merge extra-vars into
    :param extra_vars: List of extra-vars (each item should be a dict)

    :return: The updated dict ``vars_dict``
    """
    if not isinstance(vars_dict, dict):
        raise TypeError("vars_dict must be a dictionary")

    if not extra_vars:
        return vars_dict

    # If a single dict was supplied instead of a list, handle it
    if isinstance(extra_vars, dict):
        extra_items = [extra_vars]
    elif isinstance(extra_vars, (list, tuple)):
        extra_items = extra_vars
    else:
        # Allow any iterable of dict-like objects
        try:
            extra_items = list(extra_vars)
        except TypeError:
            raise TypeError("extra_vars must be a dict or list/tuple of dicts")

    for item in extra_items:
        if isinstance(item, dict):
            vars_dict.update(item)
        else:
            # Ignore non-dict items to be tolerant
            continue

    return vars_dict

def _convert_non_cli_args(self, parser_name, values_dict):
    """
    Casts arguments to correct types by modifying values_dict in place.
    By default all the values are strings.

    :param parser_name: The command name, e.g. main, virsh, ospd, etc
    :param values_dict: The dict with arguments
    :return: The modified dictionary (in place, also returned for convenience)
    """
    # Helper to try integer conversion
    def _try_int(val):
        try:
            return int(val)
        except (ValueError, TypeError):
            return None

    # Helper to try float conversion
    def _try_float(val):
        try:
            return float(val)
        except (ValueError, TypeError):
            return None

    # Boolean interpretation
    bool_true = {"true", "yes", "1", "on"}
    bool_false = {"false", "no", "0", "off"}

    # If the object itself knows about option converters for this parser,
    # attempt to use them first.  This allows the caller to supply custom
    # conversion logic while still falling back to the generic heuristics.
    converters = None
    try:
        # Expected that a `get_option_converter` method exists.
        converters = getattr(self, "get_option_converter", lambda p, n: None)(parser_name, None)
        # If the method returned a dict mapping option names to conversion callables,
        # use it.  We ignore it if conversion cannot be applied.
    except Exception:
        converters = None

    for key, val in list(values_dict.items()):
        # Skip if value is already a non-string type
        if not isinstance(val, str):
            continue

        # Strip whitespace
        txt = val.strip()
        # Preserve empty strings as empty string
        if txt == "":
            values_dict[key] = ""
            continue

        # Boolean detection
        lower = txt.lower()
        if lower in bool_true:
            values_dict[key] = True
            continue
        if lower in bool_false:
            values_dict[key] = False
            continue

        # Custom converter from parser if available
        if converters and key in converters:
            try:
                values_dict[key] = converters[key](txt)
                continue
            except Exception:
                # fall back to generic conversion
                pass

        # Try integer conversion
        int_val = _try_int(txt)
        if int_val is not None and str(int_val) == txt:
            values_dict[key] = int_val
            continue

        # Try float conversion
        float_val = _try_float(txt)
        if float_val is not None and str(float_val) == txt:
            values_dict[key] = float_val
            continue

        # Treat as comma‑separated list
        if "," in txt:
            # split and strip each item
            values_dict[key] = [item.strip() for item in txt.split(",")]
            continue

        # Default: keep as string (but normalise spacing)
        values_dict[key] = txt

    return values_dict

def get_plugin_spec_flatten_dict(plugin_dir):
    """Creates a flat dict from the plugin spec

    :param plugin_dir: A path to the plugin's dir
    :return: A flatten dictionary contains the plugin's properties
    """
    import os
    import json

    _possible_spec_files = [
        'plugin.yaml', 'plugin.yml',
        'spec.yaml', 'spec.yml',
        'plugin.json'
    ]

    spec_path = None
    for fname in _possible_spec_files:
        potential = os.path.join(plugin_dir, fname)
        if os.path.isfile(potential):
            spec_path = potential
            break

    if spec_path is None:
        # No spec file found; return empty dict
        return {}

    # Load the spec content
    data = None
    try:
        if spec_path.lower().endswith('.json'):
            with open(spec_path, 'r', encoding='utf-8') as f:
                data = json.load(f)
        else:
            # Try to load YAML; fall back to plain text if pyyaml not available
            try:
                import yaml
                with open(spec_path, 'r', encoding='utf-8') as f:
                    data = yaml.safe_load(f)
            except Exception:
                # If YAML is not available or parsing fails, treat as empty
                data = None
    except Exception:
        # On any parsing error, return an empty dict
        return {}

    if not isinstance(data, dict):
        # If the spec does not start with a dict, return empty dict
        return {}

    # Helper to flatten nested dictionaries and lists
    def _flatten(current, parent_key='', result=None):
        if result is None:
            result = {}
        if isinstance(current, dict):
            for k, v in current.items():
                new_key = f"{parent_key}.{k}" if parent_key else k
                _flatten(v, new_key, result)
        elif isinstance(current, list):
            for idx, item in enumerate(current):
                new_key = f"{parent_key}[{idx}]" if parent_key else f"[{idx}]"
                _flatten(item, new_key, result)
        else:
            result[parent_key] = current
        return result

    return _flatten(data)

def inject_config(self):
    """Set the environment variable for config path, if it is undefined."""
    env_var = getattr(self, 'config_env_var', 'CONFIG_PATH')
    if env_var in os.environ:
        return
    config_value = None
    if hasattr(self, 'config_path') and self.config_path is not None:
        config_value = str(self.config_path)
    elif hasattr(self, 'config_file') and self.config_file is not None:
        config_value = str(self.config_file)
    if config_value is not None:
        os.environ[env_var] = config_value
        try:
            logger.debug("Injected config path into %s: %s", env_var, config_value)
        except Exception:
            pass  # logger may not be available
    else:
        # No config path available; nothing to inject
        pass
